//@ts-check
/**
 * @file Flowchart grammar → flowchart AST. Flowchart and sequence are
 * the two fully-modeled diagram types; this is the first.
 *
 * Char-code recursive descent over one statement at a time. Every
 * pattern regex is a module constant used with the sticky (`y`) flag so
 * there is no per-call `RegExp` allocation; the vertex/edge chain is a
 * hand-written scan. Produces the geometry-free flowchart AST from
 * `ast.js` — nodes, edges, subgraphs, classDef/class/style, click — preserving
 * shape, label and declaration order so `to-mermaid.js` is a fixed
 * point.
 */

import {
  flowNode, flowEdge, flowSubgraph, flowClassDef, flowClass, flowStyle, flowchartAst,
} from '../ast.js';
import { failWith } from '../errors.js';
import { readNodeClick } from './click.js';
import { countCharCode } from '@jarenjs/core/string';

/**
 * Shape opener sequences, longest first, each with the closer sequences
 * that terminate it and the resulting shape name.
 * @type {[string, [string, string][]][]}
 */
const SHAPE_OPENERS = [
  ['(((', [[')))', 'doublecircle']]],
  ['[[', [[']]', 'subroutine']]],
  ['[(', [[')]', 'cylinder']]],
  ['[/', [['/]', 'parallelogram'], ['\\]', 'trapezoid']]],
  ['[\\', [['\\]', 'parallelogram_alt'], ['/]', 'trapezoid_alt']]],
  ['([', [['])', 'stadium']]],
  ['((', [['))', 'circle']]],
  ['{{', [['}}', 'hexagon']]],
  ['[', [[']', 'rect']]],
  ['(', [[')', 'round']]],
  ['{', [['}', 'diamond']]],
  ['>', [[']', 'asymmetric']]],
];

/**
 * Sticky: an edge with an inline ` text ` label between two link runs, for
 * text no link of its opening run's kind ends (`inlineText` reads the rest).
 * The opening run is exactly `--`, `==` or `-.` and a blank, as Mermaid opens
 * edge text: `A --- B --> C` is two links, never a link labelled `B`.
 */
const RE_EDGE_LABELED = /(<?)(?:--|==|-\.)\s+(.+?)\s+([-.=]{2,})([>ox]?)/y;
/** Sticky: what opens an inline label, the `<` of a two-way link included. */
const RE_EDGE_LABEL_OPEN = /(<?)(?:--|==|-\.)\s+/y;
/**
 * Sticky: an inline label with no blank after its opening run, `A--yes-->B`.
 * The text starts with no character a link run reads (`A--o` is a link with a
 * circle head, as in Mermaid) and holds no run of two link characters.
 */
const RE_EDGE_LABELED_TIGHT = /(<?)(?:--|==|-\.)(?![-.=>ox\s|])((?:[^-.=|]|[-.=](?![-.=]))+?)\s*([-.=]{2,})([>ox]?)/y;
/** Sticky: the link run (a blank before it optional) that closes a quoted inline label. */
const RE_EDGE_LABEL_CLOSE = /\s*([-.=]{2,})([>ox]?)/y;
/** Sticky: a plain link operator, or the invisible `~~~`; a tail mark `o`/`x` stands after a blank. */
const RE_EDGE_PLAIN = /(<|(?<=\s)[ox])?([-.=]{2,}|~{3,})([>ox]?)/y;
/** Sticky: an edge id before its link, `e1@-->`; the tree keeps no edge ids. */
const RE_EDGE_ID = /[A-Za-z_][\w-]*@(?=[-=.~<ox])/y;
/** `e1@{ … }`: an edge id's animation or curve, which the tree does not keep. */
const RE_EDGE_META = /^([A-Za-z_][\w-]*)@\{[\s\S]*\}$/;
/** Sticky: an identifier (vertex id, class name, …). Ids are
 * alphanumeric/underscore (plus Unicode letters) and may hold a `'`, as
 * Mermaid's do (`b'`); `-`/`.` are excluded so they cannot swallow a
 * following link operator. */
const RE_ID = /[A-Za-z0-9_'À-￿][\w'À-￿]*/y;
/** Sticky: one character an identifier may hold. */
const RE_ID_CHAR = /[\w'À-￿]/y;

/**
 * Parse a flowchart body (config already stripped) into the flowchart
 * AST. `keyword`/`firstLine` give the header; `direction` overrides.
 * @param {string[]} lines body lines
 * @param {number} lineOffset absolute line number of `lines[0]`
 * @param {string} direction detected direction
 * @returns {object}
 */
export function parseFlowchart(lines, lineOffset, direction) {
  /** @type {Map<string, object>} */
  const nodeMap = new Map();
  const nodeOrder = [];
  const edges = [];
  const subgraphs = [];
  const classDefs = [];
  const classes = [];
  const styles = [];
  /** @type {import('./click.js').NodeClick[]} */
  const clicks = [];
  /** @type {{ id: string|null, label: string, direction: string|null, nodes: string[], line: number }[]} */
  const subgraphStack = [];
  /** @type {Set<string>} */
  const edgeIds = new Set();

  const ensureNode = (id, label, shape) => {
    let node = nodeMap.get(id);
    if (node === undefined) {
      node = flowNode(id, label ?? id, shape ?? 'rect');
      nodeMap.set(id, node);
      nodeOrder.push(id);
    }
    else {
      if (label !== null && label !== undefined) node.label = label;
      // a shape comes with a label, or alone from a node's `@{ shape: … }`
      if (shape !== null && shape !== undefined) node.shape = shape;
    }
    if (subgraphStack.length > 0) {
      const group = subgraphStack[subgraphStack.length - 1];
      if (!group.nodes.includes(id)) group.nodes.push(id);
    }
    return node;
  };

  // A finished subgraph joins the list (an inner one before the one around
  // it) and, nested, is a member of the subgraph around it; one with no id
  // of its own is numbered in the order subgraphs finish, `subGraph0` on,
  // as Mermaid numbers it
  const closeSubgraph = () => {
    const group = /** @type {{ id: string|null, label: string, direction: string|null, nodes: string[], line: number }} */ (subgraphStack.pop());
    const id = group.id ?? `subGraph${subgraphs.length}`;
    subgraphs.push(flowSubgraph(id, group.label, group.direction, group.nodes));
    const outer = subgraphStack.at(-1);
    if (outer !== undefined && !outer.nodes.includes(id)) outer.nodes.push(id);
  };

  /**
   * Read a statement that opens with a keyword (`subgraph`, `end`,
   * `direction`, `classDef`, `class`, `style`, `click`, `linkStyle`).
   * @param {string} line
   * @param {number} lineNo
   * @returns {boolean} whether it was one
   */
  const readKeyword = (line, lineNo) => {
    // subgraph … end
    if (line === 'end') {
      if (subgraphStack.length === 0) failWith('mermaid/flowchart/stray-end', {}, lineNo);
      closeSubgraph();
      return true;
    }
    // `subgraph` is a keyword only as a word of its own: `subgraph1` is a node
    if (line === 'subgraph' || RE_SUBGRAPH.test(line)) {
      const rest = line.slice('subgraph'.length).trim();
      // an empty bracketed title (`subgraph s []`, `subgraph s [""]`) Mermaid
      // refuses, and a `"` in a bracketed title it does not take as quotes (a
      // bare title it reads by its lexer's words, `bareTitle`)
      if (RE_EMPTY_TITLE.test(rest)) failWith('mermaid/flowchart/subgraph-empty-title', {}, lineNo);
      const title = bracketedTitle(rest);
      // a bracket, `<`, `>` or `|` in the id before a bracketed title that is
      // not quoted, as Mermaid refuses it (`subgraph a(b) [t]`)
      const id = title === null ? '' : rest.slice(0, rest.indexOf('[')).trim();
      if (RE_ID_BRACKET.test(afterQuotedUnit(id))) failWith('mermaid/flowchart/bracket-in-subgraph-id', { id }, lineNo);
      if (title !== null && strayQuote(title)) failWith('mermaid/flowchart/quote-in-title', {}, lineNo);
      // a bracket in a title that is not quoted, as Mermaid refuses it
      if (RE_BRACKET.test(title === null ? (rest.startsWith('"') ? '' : rest) : afterQuotedUnit(title))) {
        failWith('mermaid/flowchart/bracket-in-title', {}, lineNo);
      }
      const sg = parseSubgraphHeader(rest, lineNo);
      subgraphStack.push({ id: sg.id, label: sg.label, direction: null, nodes: [], line: lineNo });
      return true;
    }
    if (line.startsWith('direction ')) {
      const dir = line.slice('direction '.length).trim();
      if (subgraphStack.length > 0) subgraphStack[subgraphStack.length - 1].direction = dir;
      return true;
    }
    if (line.startsWith('classDef ')) {
      const rest = line.slice('classDef '.length).trim();
      const sp = rest.indexOf(' ');
      if (sp === -1) classDefs.push(flowClassDef(rest, ''));
      else classDefs.push(flowClassDef(rest.slice(0, sp).trim(), rest.slice(sp + 1).trim()));
      return true;
    }
    if (line.startsWith('class ')) {
      const rest = line.slice('class '.length).trim();
      const sp = rest.lastIndexOf(' ');
      if (sp === -1) return true;
      const nodeList = rest.slice(0, sp).split(',').map((s) => s.trim()).filter(Boolean);
      const name = rest.slice(sp + 1).trim();
      for (const n of nodeList) classes.push(flowClass(n, name));
      return true;
    }
    if (line.startsWith('style ')) {
      const rest = line.slice('style '.length).trim();
      const sp = rest.indexOf(' ');
      if (sp !== -1) styles.push(flowStyle(rest.slice(0, sp).trim(), rest.slice(sp + 1).trim()));
      return true;
    }
    if (line.startsWith('click ')) {
      // a line that is none of Mermaid's click forms stays parse-accepted
      // and out of the tree, as every click line was before they were read
      const read = readNodeClick(line.endsWith(';') ? line.slice(0, -1).trimEnd() : line, true);
      if (read !== null) clicks.push(read);
      return true;
    }
    // parse-accept, not modeled in v1
    return line.startsWith('linkStyle ');
  };

  for (let li = 0; li < lines.length; li++) {
    let line = lines[li].trim();
    if (line === '') continue;
    const lineNo = lineOffset + li + 1;
    // a quoted label may run over lines (a markdown string's line breaks are
    // its own): a line no reading takes on its own, with a quote left open,
    // reads on to the line that closes it
    const joined = quotedLabelLines(lines, li, line, direction);
    if (joined !== null) {
      line = joined.line;
      li = joined.last;
    }
    // a bare `subgraph` (with at most one blank after it) names nothing, and
    // Mermaid refuses it; two blanks or more read as an untitled subgraph
    if (line === 'subgraph' && RE_BARE_SUBGRAPH.test(lines[li].trimStart())) {
      failWith('mermaid/flowchart/subgraph-unnamed', {}, lineNo);
    }
    // `subgraph ""` with nothing after it Mermaid refuses; with a blank after
    // it, it reads as an untitled subgraph
    if (line === 'subgraph ""' && lines[li].trimStart() === line) {
      failWith('mermaid/flowchart/subgraph-empty-title', {}, lineNo);
    }
    // a line that opens with a keyword is that one statement, read whole
    if (readKeyword(line, lineNo)) continue;
    // A node/edge chain: split on ';' first (multiple statements per line);
    // a statement after a ';' may be a keyword's, and a bare `subgraph`
    // ending the line is refused there as on a line of its own
    for (const stmt of splitStatements(line)) {
      if (stmt === 'subgraph' && RE_BARE_SUBGRAPH_AFTER.test(lines[li])) {
        failWith('mermaid/flowchart/subgraph-unnamed', {}, lineNo);
      }
      if (readKeyword(stmt, lineNo)) continue;
      // an edge id's `e1@{ … }` styles that edge; any other `id@{ … }` is a node
      const meta = RE_EDGE_META.exec(stmt);
      if (meta !== null && edgeIds.has(meta[1])) continue;
      parseChain(stmt, lineNo, ensureNode, edges, classes, edgeIds);
    }
  }

  // a subgraph no `end` closes Mermaid refuses
  const open = subgraphStack.at(-1);
  if (open !== undefined) failWith('mermaid/flowchart/subgraph-unclosed', { id: open.id ?? open.label }, open.line);

  const nodes = nodeOrder.map((id) => nodeMap.get(id));
  return flowchartAst(direction, nodes, edges, subgraphs, classDefs, classes, styles, clicks);
}

/** A `subgraph` line with no name, at most one blank after the keyword. */
const RE_BARE_SUBGRAPH = /^subgraph\s?$/;
/** A bare `subgraph` after a `;`, ending its line. */
const RE_BARE_SUBGRAPH_AFTER = /;\s*subgraph\s?$/;
/** A subgraph header whose bracketed title is empty: `s []` or `s [""]`. */
const RE_EMPTY_TITLE = /\[(?:"")?\]$/;
/** `subgraph` and a blank: the keyword, not a node id that begins with it. */
const RE_SUBGRAPH = /^subgraph\s/;
/** A subgraph header whose title opens with a quote: `subgraph s ["…`, `subgraph "…`. */
const RE_SUBGRAPH_QUOTED_TITLE = /^subgraph\s+(?:"|[^\s[]*\s*\[\s*")/;

/**
 * A statement whose quoted label runs over lines, as Mermaid reads it: the
 * line holds an odd number of `"` and is refused on its own, so the lines up
 * to the next one that closes the quote join it, each trimmed, at a line
 * break. Null when the line reads on its own or no later line closes it.
 * @param {string[]} lines
 * @param {number} li the line's index
 * @param {string} line the line, trimmed
 * @param {string} direction
 * @returns {{ line: string, last: number } | null}
 */
function quotedLabelLines(lines, li, line, direction) {
  // the last line has none to join (and a line read alone is the last)
  if (li === lines.length - 1 || countCharCode(line, 0x22 /* " */) % 2 === 0) return null;
  // a subgraph header reads alone with its title cut short, so one whose
  // quote opens its title (`subgraph s ["…`, `subgraph "…`) reads on
  if (RE_SUBGRAPH.test(line) ? !RE_SUBGRAPH_QUOTED_TITLE.test(line) : readsAlone(line, direction)) return null;
  let text = line;
  for (let next = li + 1; next < lines.length; next++) {
    const more = lines[next].trim();
    text += '\n' + more;
    if (countCharCode(more, 0x22) % 2 === 1) return { line: text, last: next };
  }
  return null;
}

/**
 * Does one line read as a flowchart on its own?
 * @param {string} line
 * @param {string} direction
 * @returns {boolean}
 */
function readsAlone(line, direction) {
  try {
    parseFlowchart([line], 0, direction);
    return true;
  }
  catch {
    return false;
  }
}

/**
 * Split a line on its statement separators, the `;`s outside every label.
 *
 * A label is found as the chain reader finds it, so the two never disagree on
 * where one ends: a shape's brackets directly after an id, scanned by
 * `scanToCloser` (a `"` that opens the label runs to its partner wherever
 * it stands, and a `'` counts only where it opens the label and its partner
 * meets the closer, so the apostrophe in `A[it's]` is text), and a
 * link with its pipe or inline label, read by `readEdge`, and a quoted string
 * anywhere else (a click's `"https://e.com/?a=1;b=2"`). A `;` inside a label
 * or a string is text — `"fetch is injected; streaming via SSE"` is one
 * node, and so is `[a;b]` — and every other `;` separates.
 * @param {string} line
 * @returns {string[]}
 */
function splitStatements(line) {
  if (line.indexOf(';') === -1) return [line];
  const out = [];
  /** @type {Map<[string, string][], number>} */
  const unclosed = new Map();
  let start = 0;
  for (let i = 0; i < line.length;) {
    if (line.charCodeAt(i) !== 0x3b /* ; */) {
      const end = labelEnd(line, i, unclosed);
      i = end > i ? end : i + 1;
      continue;
    }
    const part = line.slice(start, i).trim();
    if (part !== '') out.push(part);
    start = ++i;
  }
  const tail = line.slice(start).trim();
  if (tail !== '') out.push(tail);
  return out;
}

/**
 * Where a label that opens at `at` ends, as the chain reader reads it: a
 * shape directly after an id character, a link operator with its label, or
 * a quoted string.
 * @param {string} s
 * @param {number} at
 * @param {Map<[string, string][], number>} unclosed per closer set, the index
 *   from which the line holds none of them: a shape that never closes is not
 *   scanned for again, so a line of unclosed shapes splits in linear time
 * @returns {number} the index after the label, or `at` when none opens there
 */
function labelEnd(s, at, unclosed) {
  RE_ID_CHAR.lastIndex = at - 1;
  if (at > 0 && RE_ID_CHAR.test(s)) {
    const opened = matchOpener(s, at);
    if (opened !== null) {
      if (opened.contentStart >= (unclosed.get(opened.closers) ?? Infinity)) return at;
      const closed = scanToCloser(s, opened.contentStart, opened.closers);
      if (closed !== null) return closed.end;
      unclosed.set(opened.closers, opened.contentStart);
      return at;
    }
  }
  const c = s.charCodeAt(at);
  if (c === 0x2d /* - */ || c === 0x3d /* = */ || c === 0x3c /* < */) return readEdge(s, at)?.pos ?? at;
  // a quoted string of a statement (a click's link or tooltip) is one unit
  if (c === 0x22 /* " */) {
    const partner = s.indexOf('"', at + 1);
    return partner === -1 ? at : partner + 1;
  }
  return at;
}

/** A markdown string's text between its backticks. */
const RE_MARKDOWN_TITLE = /^`([\s\S]+)`$/;

/**
 * Parse `subgraph` header: `id`, `id[title]`, `"title"`, or `id [title]`.
 * A title that is also the id names the subgraph by its text (a quoted
 * markdown title without its backticks); one written with a blank in it
 * names none (nor does an empty one), and the subgraph is numbered when it
 * closes, as Mermaid numbers it.
 * @param {string} rest
 * @param {number} lineNo the header's line, for a refusal
 * @returns {{ id: string|null, label: string }}
 */
function parseSubgraphHeader(rest, lineNo) {
  if (rest === '') return { id: null, label: '' };
  // id[title] form
  const br = rest.indexOf('[');
  if (br !== -1 && rest.endsWith(']')) {
    const id = bareTitle(rest.slice(0, br).trim(), lineNo);
    const label = labelText(rest.slice(br + 1, -1).trim());
    return { id: id || label, label };
  }
  if (rest.startsWith('"') && rest.indexOf('"', 1) === rest.length - 1) {
    const label = lineBreaks(rest.slice(1, -1));
    const id = RE_MARKDOWN_TITLE.exec(label)?.[1] ?? label;
    return { id: id === '' || RE_BLANK.test(id) ? null : id, label };
  }
  const label = bareTitle(rest, lineNo);
  return { id: label === '' || RE_BLANK.test(rest) ? null : label, label };
}

/** Sticky: a word of Mermaid's lexer a `"` may stand inside (`a"b`, `-"x"`). */
const RE_TITLE_WORD = /(?:[A-Za-z0-9!"#$%&'*+.`?\\_/]|-(?=[^>\-.]))+/y;

/** Sticky: a number, which Mermaid's lexer reads before a word (`6"x"` is `6` and a string). */
const RE_TITLE_NUMBER = /[0-9]+/y;

/**
 * A bare subgraph title (or the id before a bracketed one) as Mermaid's
 * lexer reads it: a `"` that starts one
 * of its words opens a string the next `"` closes, which only the title's
 * first word may be (`"a"b` is `ab`, `"a" b` is `a b`); an empty `""` is no
 * word and is dropped (`s ""` is `s`); a `"` inside a word is text (`a"b`).
 * A string after the first word, or one never closed, is refused, as Mermaid
 * refuses it (`subgraph a "b" c`, `subgraph 6" pipes`).
 * @param {string} rest the header after `subgraph`, trimmed
 * @param {number} lineNo
 * @returns {string}
 */
function bareTitle(rest, lineNo) {
  if (!rest.includes('"')) return rest;
  let text = '';
  let first = true;
  for (let i = 0; i < rest.length;) {
    if (rest.charCodeAt(i) === 0x22 /* " */) {
      const close = rest.indexOf('"', i + 1);
      if (close === -1 || (close > i + 1 && !first)) failWith('mermaid/flowchart/quote-in-title', {}, lineNo);
      if (close > i + 1) first = false;
      text += rest.slice(i + 1, close);
      i = close + 1;
      continue;
    }
    first = false;
    RE_TITLE_NUMBER.lastIndex = i;
    RE_TITLE_WORD.lastIndex = i;
    const end = RE_TITLE_NUMBER.test(rest) ? RE_TITLE_NUMBER.lastIndex : RE_TITLE_WORD.test(rest) ? RE_TITLE_WORD.lastIndex : i + 1;
    text += rest.slice(i, end);
    i = end;
  }
  return text.trim();
}

/**
 * A subgraph header's title in brackets, as written; null where it has none.
 * @param {string} rest the header after `subgraph`
 * @returns {string | null}
 */
function bracketedTitle(rest) {
  const br = rest.indexOf('[');
  return br !== -1 && rest.endsWith(']') ? rest.slice(br + 1, -1).trim() : null;
}

/**
 * Does a label as written hold a `"` Mermaid refuses: one outside the
 * `"…"` unit a label may open with (`'…'` is no quoting to Mermaid), but for
 * the empty `""` pairs it drops (`a"b`, `"a"b"c"` and `"a" "b"` are refused;
 * `a""b`, `"a"b` and `""a""` read)?
 * @param {string} written the label, trimmed
 * @returns {boolean}
 */
function strayQuote(written) {
  return afterQuotedUnit(written).replaceAll('""', '').includes('"');
}

/**
 * A label as written after the `"…"` unit it opens with, or the whole label
 * where it opens with none.
 * @param {string} written
 * @returns {string}
 */
function afterQuotedUnit(written) {
  return written.charCodeAt(0) === 0x22 ? written.slice(written.indexOf('"', 1) + 1) : written;
}

/**
 * A label as it reads, from the label as written, as Mermaid reads it: the
 * `"…"` unit it may open with joined to the text after it, without the
 * empty `""` pairs Mermaid drops (`"x"y` is `xy`, `"a] --> B["b` is
 * `a] --> B[b`, `a""b` is `ab`), then its `"…"` quotes stripped; `'…'`
 * is text.
 * @param {string} written the label, trimmed
 * @returns {string}
 */
function labelText(written) {
  const rest = afterQuotedUnit(written).replaceAll('""', '');
  // `'…'` is no quoting to Mermaid: `A['x']` is the text `'x'`
  if (written.charCodeAt(0) !== 0x22) return lineBreaks(rest);
  // the unit and the text after it, read as one quoted unit
  return stripQuotes(`"${written.slice(1, written.length - afterQuotedUnit(written).length - 1)}${rest}"`);
}

/** A blank anywhere in a title: such a title names no subgraph. */
const RE_BLANK = /\s/;

/** The most edges one flowchart may declare. */
const MAX_EDGES = 10000;

/**
 * Parse one vertex/edge chain: `A[x] --> B & C -->|l| D`.
 * @param {string} stmt
 * @param {number} lineNo
 * @param {(id: string, label: string|null, shape: string|null) => object} ensureNode
 * @param {object[]} edges
 * @param {object[]} classes
 * @param {Set<string>} edgeIds the edge ids read so far
 */
function parseChain(stmt, lineNo, ensureNode, edges, classes, edgeIds) {
  const s = stmt;
  let pos = skipSpace(s, 0);
  let prevGroup = readVertexGroup(s, pos, lineNo, ensureNode, classes);
  if (prevGroup === null) return; // empty
  pos = prevGroup.pos;

  // Standalone vertex (no edge): already ensured; done.
  for (;;) {
    pos = skipSpace(s, pos);
    if (pos >= s.length) break;
    RE_EDGE_ID.lastIndex = pos;
    if (RE_EDGE_ID.test(s)) {
      edgeIds.add(s.slice(pos, RE_EDGE_ID.lastIndex - 1));
      pos = RE_EDGE_ID.lastIndex;
    }
    const edge = readEdge(s, pos);
    // what follows a node is a link or nothing, as in Mermaid: trailing text
    // is refused, where it was dropped without a word
    if (edge === null) failWith('mermaid/flowchart/expected-link', { rest: s.slice(pos) }, lineNo);
    // a `"` in a link's label that opens with no quote, and a label with
    // nothing in it, as Mermaid refuses them
    if (edge.stray) failWith('mermaid/flowchart/quote-in-link-label', { from: prevGroup.ids.join(' & ') }, lineNo);
    if (edge.empty) failWith('mermaid/flowchart/empty-link-label', { from: prevGroup.ids.join(' & ') }, lineNo);
    if (edge.bracket) failWith('mermaid/flowchart/bracket-in-link-label', { from: prevGroup.ids.join(' & ') }, lineNo);
    if (edge.run !== null) failWith('mermaid/flowchart/link-in-link-label', { from: prevGroup.ids.join(' & '), run: edge.run }, lineNo);
    pos = edge.pos;
    pos = skipSpace(s, pos);
    const nextGroup = readVertexGroup(s, pos, lineNo, ensureNode, classes);
    if (nextGroup === null) failWith('mermaid/flowchart/expected-node', {}, lineNo);
    pos = nextGroup.pos;
    // `A & B & … --> C & D & …` is a link per pair, so a few kilobytes of
    // source can name millions of edges
    if (edges.length + prevGroup.ids.length * nextGroup.ids.length > MAX_EDGES) {
      failWith('mermaid/flowchart/too-many-edges', { max: MAX_EDGES }, lineNo);
    }
    for (const from of prevGroup.ids) {
      for (const to of nextGroup.ids) {
        edges.push(flowEdge(from, to, edge.stroke, edge.head, edge.tail, edge.length, edge.label));
      }
    }
    prevGroup = nextGroup;
  }
}

/**
 * Read a `&`-separated vertex group, ensuring each node.
 * @returns {{ ids: string[], pos: number } | null}
 */
function readVertexGroup(s, pos, lineNo, ensureNode, classes) {
  const ids = [];
  for (;;) {
    pos = skipSpace(s, pos);
    const v = readVertex(s, pos, lineNo);
    if (v === null) return ids.length === 0 ? null : { ids, pos };
    ensureNode(v.id, v.label, v.shape);
    if (v.className !== null) classes.push(flowClass(v.id, v.className));
    ids.push(v.id);
    pos = skipSpace(s, v.pos);
    if (s.charCodeAt(pos) === 0x26 /* & */) { pos++; continue; }
    return { ids, pos };
  }
}

/**
 * Read one vertex: id + optional shape/label + optional `:::class`.
 * @returns {{ id: string, label: string|null, shape: string|null, className: string|null, pos: number } | null}
 */
function readVertex(s, pos, lineNo) {
  RE_ID.lastIndex = pos;
  const m = RE_ID.exec(s);
  if (m === null || m.index !== pos) return null;
  const id = m[0];
  let p = RE_ID.lastIndex;

  let label = null;
  let shape = null;
  // Shape wrapper directly after the id (no space).
  const opened = matchOpener(s, p);
  if (opened !== null) {
    const closed = scanToCloser(s, opened.contentStart, opened.closers);
    if (closed === null) {
      // a quote that opens the label and nothing closes, as Mermaid refuses it
      if (s.slice(opened.contentStart).trimStart().startsWith('"') && countCharCode(s.slice(opened.contentStart), 0x22) % 2 === 1) {
        failWith('mermaid/flowchart/quote-unclosed', { id }, lineNo);
      }
      failWith('mermaid/flowchart/unterminated-shape', { opener: opened.opener, id }, lineNo);
    }
    const raw = s.slice(opened.contentStart, closed.at);
    // a label with nothing in it, but for the empty `""` pairs Mermaid drops,
    // is refused, as Mermaid refuses it (`A[]`, `A[""]`; `A[ ]` reads)
    if (raw.replaceAll('""', '') === '') failWith('mermaid/flowchart/empty-label', { id }, lineNo);
    const written = raw.trim();
    // a `"` in a label that opens with no quote is refused, as Mermaid
    // refuses it (in `'…'` too, no quoting to Mermaid), where it was read as
    // text; an empty `""` Mermaid drops
    if (strayQuote(written)) {
      failWith('mermaid/flowchart/quote-in-label', { id }, lineNo);
    }
    label = labelText(written);
    shape = closed.shape;
    p = closed.end;
  }

  // Inline class: A:::name
  let className = null;
  if (s.charCodeAt(p) === 0x3a && s.charCodeAt(p + 1) === 0x3a && s.charCodeAt(p + 2) === 0x3a) {
    RE_ID.lastIndex = p + 3;
    const cm = RE_ID.exec(s);
    if (cm !== null && cm.index === p + 3) {
      className = cm[0];
      p = RE_ID.lastIndex;
    }
  }
  // `A@{ shape: …, label: … }`: the node's metadata sets its shape and label
  if (s.charCodeAt(p) === 0x40 /* @ */ && s.charCodeAt(p + 1) === 0x7b /* { */) {
    const end = metadataEnd(s, p + 2);
    if (end !== -1) {
      const meta = nodeMetadata(s.slice(p + 2, end - 1));
      if (meta.unknown !== null) failWith('mermaid/flowchart/unknown-shape', { id, shape: meta.unknown }, lineNo);
      if (meta.label !== null) label = meta.label;
      if (meta.shape !== null) shape = meta.shape;
      p = end;
    }
  }
  return { id, label, shape, className, pos: p };
}

/**
 * Mermaid's shape names (each short name and alias) for the shapes this tree
 * draws, as this tree names them: a shape with a bracket form by its
 * bracket form's name (`diamond`, `cylinder`, …), any other by Mermaid's
 * short name (`doc`, `flip-tri`, …), which `toMermaid` prints back.
 */
const METADATA_SHAPES = /** @type {Record<string, string>} */ ({
  __proto__: null,
  rect: 'rect', proc: 'rect', process: 'rect', rectangle: 'rect',
  rounded: 'round', event: 'round',
  stadium: 'stadium', terminal: 'stadium', pill: 'stadium',
  'fr-rect': 'subroutine', subprocess: 'subroutine', subproc: 'subroutine',
  'framed-rectangle': 'subroutine', subroutine: 'subroutine',
  cyl: 'cylinder', db: 'cylinder', database: 'cylinder', cylinder: 'cylinder',
  circle: 'circle', circ: 'circle',
  diam: 'diamond', decision: 'diamond', diamond: 'diamond', question: 'diamond',
  hex: 'hexagon', hexagon: 'hexagon', prepare: 'hexagon',
  'lean-r': 'parallelogram', 'lean-right': 'parallelogram', 'in-out': 'parallelogram',
  'lean-l': 'parallelogram_alt', 'lean-left': 'parallelogram_alt', 'out-in': 'parallelogram_alt',
  'trap-b': 'trapezoid', priority: 'trapezoid', 'trapezoid-bottom': 'trapezoid', trapezoid: 'trapezoid',
  'trap-t': 'trapezoid_alt', manual: 'trapezoid_alt', 'trapezoid-top': 'trapezoid_alt',
  'inv-trapezoid': 'trapezoid_alt',
  'dbl-circ': 'doublecircle', 'double-circle': 'doublecircle', doublecircle: 'doublecircle',
  odd: 'asymmetric',
  datastore: 'datastore', 'data-store': 'datastore',
  bang: 'bang', cloud: 'cloud', text: 'text',
  'notch-rect': 'notch-rect', card: 'notch-rect', 'notched-rectangle': 'notch-rect',
  'lin-rect': 'lin-rect', 'lined-rectangle': 'lin-rect', 'lined-process': 'lin-rect', 'lin-proc': 'lin-rect',
  'shaded-process': 'lin-rect',
  'sm-circ': 'sm-circ', start: 'sm-circ', 'small-circle': 'sm-circ',
  'fr-circ': 'fr-circ', stop: 'fr-circ', 'framed-circle': 'fr-circ',
  fork: 'fork', join: 'fork',
  hourglass: 'hourglass', collate: 'hourglass',
  brace: 'brace', comment: 'brace', 'brace-l': 'brace', 'brace-r': 'brace-r', braces: 'braces',
  bolt: 'bolt', 'com-link': 'bolt', 'lightning-bolt': 'bolt',
  doc: 'doc', document: 'doc',
  delay: 'delay', 'half-rounded-rectangle': 'delay',
  'h-cyl': 'h-cyl', das: 'h-cyl', 'horizontal-cylinder': 'h-cyl',
  'lin-cyl': 'lin-cyl', disk: 'lin-cyl', 'lined-cylinder': 'lin-cyl',
  'curv-trap': 'curv-trap', 'curved-trapezoid': 'curv-trap', display: 'curv-trap',
  'div-rect': 'div-rect', 'div-proc': 'div-rect', 'divided-rectangle': 'div-rect', 'divided-process': 'div-rect',
  tri: 'tri', extract: 'tri', triangle: 'tri',
  'win-pane': 'win-pane', 'internal-storage': 'win-pane', 'window-pane': 'win-pane',
  'f-circ': 'f-circ', junction: 'f-circ', 'filled-circle': 'f-circ',
  'notch-pent': 'notch-pent', 'loop-limit': 'notch-pent', 'notched-pentagon': 'notch-pent',
  'flip-tri': 'flip-tri', 'manual-file': 'flip-tri', 'flipped-triangle': 'flip-tri',
  'sl-rect': 'sl-rect', 'manual-input': 'sl-rect', 'sloped-rectangle': 'sl-rect',
  docs: 'docs', documents: 'docs', 'st-doc': 'docs', 'stacked-document': 'docs',
  'st-rect': 'st-rect', procs: 'st-rect', processes: 'st-rect', 'stacked-rectangle': 'st-rect',
  'bow-rect': 'bow-rect', 'stored-data': 'bow-rect', 'bow-tie-rectangle': 'bow-rect',
  'cross-circ': 'cross-circ', summary: 'cross-circ', 'crossed-circle': 'cross-circ',
  'tag-doc': 'tag-doc', 'tagged-document': 'tag-doc',
  'tag-rect': 'tag-rect', 'tagged-rectangle': 'tag-rect', 'tag-proc': 'tag-rect', 'tagged-process': 'tag-rect',
  flag: 'flag', 'paper-tape': 'flag',
  'lin-doc': 'lin-doc', 'lined-document': 'lin-doc',
});

/**
 * Mermaid's shape names this tree draws no shape of its own for: a node
 * that asks for one is drawn a rectangle.
 */
const UNDRAWN_SHAPES = new Set(['state', 'choice', 'note', 'icon', 'anchor']);

/** One `key: value` entry of a node's metadata; the value may be quoted. */
const RE_METADATA_ENTRY = /\s*([\w-]+)\s*:\s*("[^"]*"|'[^']*'|[^,]*?)\s*(?:,|$)/y;

/**
 * Read a node's `@{ … }` metadata as Mermaid does: its `label`, and its
 * `shape` by Mermaid's name for it. A shape name Mermaid does not know (it
 * refuses the diagram) is `unknown`, for the reader to refuse; the rest of
 * the entries (`icon`, `img`, `pos`, …) are not kept.
 * @param {string} body the text between `@{` and `}`
 * @returns {{ label: string|null, shape: string|null, unknown: string|null }}
 */
function nodeMetadata(body) {
  let label = null;
  let shape = null;
  let unknown = null;
  RE_METADATA_ENTRY.lastIndex = 0;
  for (let m; RE_METADATA_ENTRY.lastIndex < body.length && (m = RE_METADATA_ENTRY.exec(body)) !== null;) {
    if (m[0] === '') break;
    // an empty label is none: the node shows its id
    if (m[1] === 'label') label = stripQuotes(m[2]) || label;
    else if (m[1] === 'shape') {
      const name = stripQuotes(m[2]);
      shape = METADATA_SHAPES[name] ?? (UNDRAWN_SHAPES.has(name) ? 'rect' : null);
      unknown = shape === null && name !== '' ? name : null;
    }
  }
  return { label, shape, unknown };
}

/**
 * Where a node's `@{ … }` metadata ends: after the `}` that closes it,
 * outside its quoted values; -1 when none does.
 * @param {string} s
 * @param {number} from the index after the `@{`
 * @returns {number}
 */
function metadataEnd(s, from) {
  for (let i = from; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x7d /* } */) return i + 1;
    if (c === 0x22 /* " */) {
      const close = s.indexOf('"', i + 1);
      if (close === -1) return -1;
      i = close;
    }
  }
  return -1;
}

/**
 * Match a shape opener at `pos` (longest first).
 * @returns {{ opener: string, contentStart: number, closers: [string, string][] } | null}
 */
function matchOpener(s, pos) {
  for (let i = 0; i < SHAPE_OPENERS.length; i++) {
    const [opener, closers] = SHAPE_OPENERS[i];
    if (s.startsWith(opener, pos)) {
      return { opener, contentStart: pos + opener.length, closers };
    }
  }
  return null;
}

/** The closer of a pipe-form edge label. */
const PIPE_CLOSER = /** @type {[string, string][]} */ ([['|', 'edge']]);


/**
 * Scan for the earliest closer sequence from `from`. A label that opens
 * with a `"` reads as Mermaid reads it: each `"…"` is one unit, running to
 * the next `"` wherever it stands (past brackets and links:
 * `A["x] --> B[y"]` is one node), and one no `"` closes ends nothing (null,
 * for the reader to refuse). Any other label is scanned as written: `'…'` is
 * no quoting to Mermaid (`A['a]b']` closes at the first `]`).
 * @param {string} s
 * @param {number} from
 * @param {[string, string][]} closers
 * @returns {{ at: number, end: number, shape: string } | null}
 */
function scanToCloser(s, from, closers) {
  let start = from;
  while (start < s.length && (s.charCodeAt(start) === 0x20 || s.charCodeAt(start) === 0x09)) start++;
  const quote = s[start];
  if (quote === '"') return closerAfterQuotes(s, start, closers);
  return firstCloser(s, from, closers);
}

/**
 * The earliest closer of a label that opens with the `"` at `at`, outside
 * every `"…"` unit of it; null when a `"` is never closed.
 * @param {string} s
 * @param {number} at
 * @param {[string, string][]} closers
 * @returns {{ at: number, end: number, shape: string } | null}
 */
function closerAfterQuotes(s, at, closers) {
  for (let i = at; i < s.length; i++) {
    if (s.charCodeAt(i) === 0x22 /* " */) {
      i = s.indexOf('"', i + 1);
      if (i === -1) return null;
      continue;
    }
    for (let c = 0; c < closers.length; c++) {
      const [seq, shape] = closers[c];
      if (s.startsWith(seq, i)) return { at: i, end: i + seq.length, shape };
    }
  }
  return null;
}

/**
 * The earliest closer sequence from `from`.
 * @param {string} s
 * @param {number} from
 * @param {[string, string][]} closers
 * @returns {{ at: number, end: number, shape: string } | null}
 */
function firstCloser(s, from, closers) {
  for (let i = from; i < s.length; i++) {
    for (let c = 0; c < closers.length; c++) {
      const [seq, shape] = closers[c];
      if (s.startsWith(seq, i)) return { at: i, end: i + seq.length, shape };
    }
  }
  return null;
}

/**
 * A link's label as it reads, from the label as written: its quotes
 * stripped, the empty `""` pairs Mermaid drops dropped, whether it holds
 * a `"` Mermaid refuses (`strayQuote`), and whether it holds nothing else,
 * which Mermaid refuses (`||`, `|""|`, `-- "" -->`; a blank between pipes
 * reads, the blanks of the inline form are its markers'), and whether, between
 * pipes, it holds a bracket outside its quoted unit, which Mermaid refuses
 * (`|x(y)|`; the inline form `-- x(y) -->` reads).
 * @param {string} written
 * @param {boolean} [piped] written between pipes, where a blank is text
 * @returns {{ label: string, stray: boolean, empty: boolean, bracket: boolean }}
 */
function edgeLabel(written, piped = false) {
  const text = written.trim();
  return { label: labelText(text), stray: strayQuote(text), empty: (piped ? written : text).replaceAll('""', '') === '',
    bracket: piped && RE_BRACKET.test(afterQuotedUnit(text)) };
}

/** A bracket of a shape (`(`, `)`, `[`, `]`, `{`, `}`), which Mermaid refuses in a pipe label or title that is not quoted. */
const RE_BRACKET = /[()[\]{}]/;

/** What Mermaid's lexer reads as no part of a subgraph id: a bracket, `<`, `>` or `|`. */
const RE_ID_BRACKET = /[()[\]{}<>|]/;

/**
 * Read a link operator, plain or labeled; `stray` tells a label holding a
 * `"` Mermaid refuses, `empty` one holding nothing, `bracket` one holding
 * a bracket it refuses and `run` the run in an inline label's text that ends
 * no link of its kind (`--` in `A -- a -- b --> B`), for the chain reader to
 * refuse.
 * @returns {{ stroke: string, head: string, tail: string, length: number, label: string|null, stray: boolean, empty: boolean, bracket: boolean, run: string|null, pos: number } | null}
 */
function readEdge(s, pos) {
  let label = null;
  RE_EDGE_LABEL_OPEN.lastIndex = pos;
  const open = RE_EDGE_LABEL_OPEN.exec(s);
  if (open !== null) {
    // a quoted label is one unit, as in the pipe form: the link operators
    // inside its quotes are text, so `A -- "a --> b" --> B` is one edge
    // (`'…'` is no quoting to Mermaid: `A -- 'a --> b' --> B` is a link
    // labelled `'a` to a node `b'`)
    const text = RE_EDGE_LABEL_OPEN.lastIndex;
    const partner = s[text] === '"' ? s.indexOf('"', text + 1) : -1;
    if (partner !== -1) {
      RE_EDGE_LABEL_CLOSE.lastIndex = partner + 1;
      const close = RE_EDGE_LABEL_CLOSE.exec(s);
      if (close !== null) {
        const info = classifyLink(open[1], close[1], close[2]);
        return { ...info, ...edgeLabel(s.slice(text, partner + 1)), run: null, pos: RE_EDGE_LABEL_CLOSE.lastIndex };
      }
    }
    // the text runs to the first link of the opening run's kind, as Mermaid
    // lexes it; a run that ends no such link is refused, as Mermaid refuses
    // it (`A -- a -- b --> B`)
    const inline = inlineText(s, text, open[0].trim().slice(open[1].length));
    if (inline !== null) {
      if (inline.run !== null) return { stroke: 'solid', head: 'none', tail: 'none', length: 1, label: null, stray: false, empty: false, bracket: false, run: inline.run, pos: text };
      const info = classifyLink(open[1], inline.body, inline.head);
      return { ...info, ...edgeLabel(s.slice(text, inline.at)), run: null, pos: inline.end };
    }
    RE_EDGE_LABELED.lastIndex = pos;
    const m = RE_EDGE_LABELED.exec(s);
    if (m !== null) {
      // the inline form's text reads as the pipe form's: quotes stripped and
      // `<br>` a line break, as Mermaid reads both
      const info = classifyLink(m[1], m[3], m[4]);
      return { ...info, ...edgeLabel(m[2]), run: null, pos: RE_EDGE_LABELED.lastIndex };
    }
  }
  RE_EDGE_LABELED_TIGHT.lastIndex = pos;
  const tight = RE_EDGE_LABELED_TIGHT.exec(s);
  if (tight !== null) {
    const info = classifyLink(tight[1], tight[3], tight[4]);
    return { ...info, ...edgeLabel(tight[2]), run: null, pos: RE_EDGE_LABELED_TIGHT.lastIndex };
  }
  RE_EDGE_PLAIN.lastIndex = pos;
  const m = RE_EDGE_PLAIN.exec(s);
  if (m === null || m.index !== pos) return null;
  const info = classifyLink(m[1] ?? '', m[2], m[3]);
  let p = RE_EDGE_PLAIN.lastIndex;
  let stray = false;
  let empty = false;
  let bracket = false;
  // Optional |label|, blanks before it allowed: a quoted label is one unit,
  // as in a node's brackets, so `|"x|y"|` reads `x|y`
  const pipe = skipSpace(s, p);
  if (s.charCodeAt(pipe) === 0x7c /* | */) {
    const close = scanToCloser(s, pipe + 1, PIPE_CLOSER);
    if (close !== null) {
      ({ label, stray, empty, bracket } = edgeLabel(s.slice(pipe + 1, close.at), true));
      p = close.end;
    }
  }
  return { ...info, label, stray, empty, bracket, run: null, pos: p };
}

/**
 * Mermaid's lexer for an inline label's text, by the run that opens it: the
 * link that ends the text (`--` text ends at `---`, `-->`, `--x`, `--o`, a
 * longer run too), and the one character the text may hold (a `-` not before
 * another, no `=` in `==` text, no `.` in `-.` text). A mark before the
 * closing run (`x-->`) is its own, not the text's.
 * @type {Record<string, { close: RegExp, text: RegExp, kind: string }>}
 */
const INLINE_TEXT = {
  __proto__: null,
  '--': { close: /\s*[xo<]?(-{2,}(?=[-xo>])-*)([xo>]?)\s*/y, text: /[^-]|-(?!-)/y, kind: '--' },
  '==': { close: /\s*[xo<]?(={2,}(?=[=xo>])=*)([xo>]?)\s*/y, text: /[^=]/y, kind: '==' },
  '-.': { close: /\s*[xo<]?(-?\.+-)([xo>]?)\s*/y, text: /[^.]/y, kind: '-.' },
};

/**
 * Where an inline label's text, read from `from` as Mermaid's lexer reads
 * it, ends: at the first link of its opening run's kind (a `"…"` string in
 * it is one unit), the link's body and head mark; or the run it holds that
 * ends no such link (`--` in `--` text, `=` in `==` text, `.` in `-.`
 * text), which Mermaid refuses. Null when no link of its kind ends it.
 * @param {string} s
 * @param {number} from where the text starts, after the opening run's blanks
 * @param {string} opening the opening run (`--`, `==`, `-.`)
 * @returns {{ at: number, body: string, head: string, end: number, run: null } | { run: string } | null}
 */
function inlineText(s, from, opening) {
  const lexer = INLINE_TEXT[opening];
  for (let i = from; i < s.length;) {
    if (s.charCodeAt(i) === 0x22 /* " */) {
      const partner = s.indexOf('"', i + 1);
      if (partner !== -1) { i = partner + 1; continue; }
    }
    lexer.close.lastIndex = i;
    const close = lexer.close.exec(s);
    if (close !== null && i > from) return { at: i, body: close[1], head: close[2], end: lexer.close.lastIndex, run: null };
    lexer.text.lastIndex = i;
    if (lexer.text.test(s)) { i++; continue; }
    return { run: opening === '--' ? '--' : s[i] };
  }
  return null;
}

/**
 * Classify a link body into stroke/head/tail/length.
 * @param {string} tailMark leading `<`/`o`/`x` or ''
 * @param {string} body run of `-`/`.`/`=`, or of `~` (an invisible link)
 * @param {string} headMark trailing `>`/`o`/`x` or ''
 */
function classifyLink(tailMark, body, headMark) {
  const stroke = body.charCodeAt(0) === 0x7e /* ~ */ ? 'invisible'
    : body.indexOf('=') !== -1 ? 'thick'
      : body.indexOf('.') !== -1 ? 'dotted' : 'solid';
  const head = headMark === '>' ? 'arrow' : headMark === 'o' ? 'circle'
    : headMark === 'x' ? 'cross' : 'none';
  const tail = tailMark === '<' ? 'arrow' : tailMark === 'o' ? 'circle'
    : tailMark === 'x' ? 'cross' : 'none';
  let length;
  if (stroke === 'invisible') length = body.length;
  else if (stroke === 'thick') length = countCharCode(body, 0x3d);
  else if (stroke === 'dotted') length = countCharCode(body, 0x2e);
  else length = countCharCode(body, 0x2d);
  if (length < 1) length = 1;
  return { stroke, head, tail, length };
}

/**
 * @param {string} s @param {number} pos @returns {number}
 */
function skipSpace(s, pos) {
  while (pos < s.length) {
    const c = s.charCodeAt(pos);
    if (c !== 0x20 && c !== 0x09) break;
    pos++;
  }
  return pos;
}

/**
 * Strip surrounding matching quotes (`"…"` or `'…'`) from a label, its
 * `<br>`s read as line breaks (`lineBreaks`).
 * @param {string} s @returns {string}
 */
export function stripQuotes(s) {
  let out = s;
  if (out.length >= 2) {
    const a = out.charCodeAt(0);
    const b = out.charCodeAt(out.length - 1);
    if ((a === 0x22 && b === 0x22) || (a === 0x27 && b === 0x27)) out = out.slice(1, -1);
  }
  return lineBreaks(out);
}

/**
 * A label's `<br>`s as line breaks. `<br/>` is Mermaid's line break inside a
 * label. Normalizing it to a real newline where a label is read is what lets
 * both the text measurement and the renderer treat it as one, instead of
 * printing the tag and sizing the box for a single long line.
 * @param {string} s @returns {string}
 */
function lineBreaks(s) {
  return RE_BR.test(s) ? s.replace(RE_BR, '\n') : s;
}

/** `<br>`, `<br/>`, `<br />` — the spellings Mermaid accepts. */
const RE_BR = /<br\s*\/?>/gi;
