//@ts-check
/**
 * @file Canonical Mermaid printer: AST → text (MERMAID-FORMAT §5).
 * The reverse arrow of `parseMermaid`, mirroring
 * `@jarenjs/md`'s `to-md.js`: one specialized closure per diagram type,
 * a **round-trip fixed point** — `parseMermaid(toMermaid(doc))`
 * deep-equals `doc.ast` for the fully-modeled types (but for text holding a
 * character Mermaid reads nowhere it stands, which reads back spelled with
 * its entity code: a label's or tooltip's `"` as `#34;` (`labelSource`,
 * `inQuotes`), a `;` in sequence text or a class relation label as `#59;`
 * (`semicolonsCoded`), a class generic's nesting as `#lt;`/`#gt;`).
 *
 * The printer is *canonical*, not verbatim: it does not preserve source
 * whitespace or comments (the stored Markdown fence `value` gives
 * verbatim round-trip while a node is untransformed). Its job is
 * to re-emit an edited AST as editable Mermaid text.
 */

import { parseState, stateStatements, stateDeclaration } from './parser/state.js';
import { printClick, printNodeClick } from './parser/click.js';
import { RE_BACKTICK_KEYWORD } from './parser/class.js';
import { isMarkdownString, genericText } from './label-text.js';
import { FLOW_NAMED_SHAPES } from './ast.js';

//#region public ----------------------------------------------------

/** @type {Record<string, (ast: any) => string>} */
const PRINTERS = {
  flowchart: printFlowchart,
  sequence: printSequence,
  class: printClass,
  state: printState,
  er: printEr,
  gantt: printGantt,
  pie: printPie,
};

/**
 * Print a `DiagramDocument` (or a bare AST with a `diagram` field) to
 * canonical Mermaid text. Config re-emits as a `%%{init}%%` header when
 * present.
 * @param {any} docOrAst
 * @returns {string}
 */
export function toMermaid(docOrAst) {
  const doc = docOrAst && typeof docOrAst === 'object' && docOrAst.$mermaid !== undefined
    ? docOrAst
    : null;
  const diagram = doc ? doc.diagram : docOrAst?.diagram;
  const ast = doc ? doc.ast : docOrAst;
  const config = doc ? doc.config : undefined;
  const title = doc ? doc.meta?.title : undefined;

  let head = '';
  if (title != null && title !== '') {
    head += '---\ntitle: ' + title + '\n---\n';
  }
  if (config && typeof config === 'object' && Object.keys(config).length > 0) {
    head += '%%{init: ' + JSON.stringify(config) + '}%%\n';
  }

  const printer = PRINTERS[diagram];
  if (printer !== undefined) return head + printer(ast);
  // Secondary/raw diagram: keyword + preserved body lines.
  if (ast && Array.isArray(ast.lines)) {
    return head + ast.diagram + '\n' + ast.lines.join('\n') + '\n';
  }
  return head + String(diagram ?? '') + '\n';
}

//#endregion
//#region flowchart -------------------------------------------------

/**
 * What a node label needs its quotes for: delimiters and literal quotes. A
 * slash or backslash at either end would join the shape's own brackets
 * (`[/x` opens a parallelogram), and outer whitespace is trimmed on the way
 * back in.
 */
const RE_NEEDS_QUOTE = /[[\](){}<>|"';]|^[\s/\\]|[\s/\\]$/;

/**
 * What a pipe-form edge label needs its quotes for: a `|` (which ends it), a
 * `;` (quoted, so the label is one unit to a reader that splits statements
 * before it reads labels), a bracket (Mermaid refuses one in an unquoted
 * label), and a quote or a space at either end (stripped or trimmed on the
 * way back in).
 */
const RE_EDGE_NEEDS_QUOTE = /[|;[\](){}]|^[\s"']|[\s"']$/;

/**
 * What a subgraph title, which runs to its line's last `]`, needs its quotes
 * for: a bracket (Mermaid refuses one in an unquoted title), a `;` (as an
 * entity code ends with one, so a coded title prints as it did when it held
 * the quote), and a quote or a space at either end.
 */
const RE_TITLE_NEEDS_QUOTE = /[[\](){};]|^[\s"']|[\s"']$/;

/**
 * What a subgraph id before its bracketed title needs its quotes for: a
 * bracket, `<`, `>` or `|`, which Mermaid reads in no unquoted id.
 */
const RE_SUBGRAPH_ID_NEEDS_QUOTE = /[()[\]{}<>|]/;

/**
 * A label as source text that reads back as the same label. A line break
 * prints as `<br/>` (printed raw it would end the statement), but in a
 * markdown string as itself, the quoted label running on to the next line. A label that
 * `needsQuote` matches, and a markdown string (unquoted, its backticks are
 * plain text), print in `"…"`; a quoted label is one unit, so its delimiters
 * are text.
 *
 * Mermaid reads a `"` in no label (it has no escape inside a quoted one, and
 * refuses one in an unquoted one; `'…'` is no quoting to it), so a label
 * holding a `"` prints in `"…"` with each `"` as its entity code `#34;`,
 * which renders as the quote and reads back as the code. An empty label
 * prints as a blank, which reads back empty (Mermaid refuses `A[]`).
 * @param {string} label
 * @param {RegExp} needsQuote what the label needs its quotes for where it stands
 * @returns {string}
 */
function labelSource(label, needsQuote) {
  if (label === '') return ' ';
  // a markdown string breaks its lines as Mermaid writes it, at a newline
  // inside its quotes (one with a quote of its own prints `<br/>`)
  let text = isMarkdownString(label) && !/["']/.test(label) ? label : label.replace(/\n/g, '<br/>');
  const coded = text.includes('"');
  if (coded) text = text.replaceAll('"', '#34;');
  if (!coded && !needsQuote.test(text) && !isMarkdownString(text)) return text;
  return '"' + text + '"';
}

/**
 * Text in `"…"`, where Mermaid has no escape: each `"` it holds written as
 * its entity code `#34;`, which renders as the quote and reads back as the
 * code.
 * @param {string} text
 * @returns {string}
 */
function inQuotes(text) {
  return `"${text.replaceAll('"', '#34;')}"`;
}

/**
 * Which subgraph each subgraph holds, by the member id that names it: the
 * nearest subgraph before it in the list with that id (the reader lists an
 * inner subgraph before the one around it) that no other subgraph holds
 * yet, then the nearest after it. A node of the same id stays declared on
 * its own line, so it reads back too.
 * @param {any} ast a flowchart tree
 * @returns {Map<object, Map<string, object>>}
 */
function nestedSubgraphs(ast) {
  /** @type {Map<object, Map<string, object>>} */
  const inner = new Map();
  const held = new Set();
  const list = ast.subgraphs;
  for (let at = 0; at < list.length; at++) {
    for (const id of list[at].nodes) {
      const pick = (/** @type {number} */ i) => i !== at && list[i].id === id && !held.has(list[i]) && !holds(inner, list[i], list[at]);
      let found = -1;
      for (let i = at - 1; i >= 0 && found === -1; i--) if (pick(i)) found = i;
      for (let i = at + 1; i < list.length && found === -1; i++) if (pick(i)) found = i;
      if (found === -1) continue;
      held.add(list[found]);
      let children = inner.get(list[at]);
      if (children === undefined) inner.set(list[at], children = new Map());
      children.set(id, list[found]);
    }
  }
  return inner;
}

/**
 * Whether `outer` holds `sg`, directly or through the subgraphs it holds.
 * @param {Map<object, Map<string, object>>} inner
 * @param {object} outer
 * @param {object} sg
 * @returns {boolean}
 */
function holds(inner, outer, sg) {
  const seen = new Set();
  const stack = [outer];
  while (stack.length > 0) {
    const at = /** @type {object} */ (stack.pop());
    if (at === sg) return true;
    if (seen.has(at)) continue;
    seen.add(at);
    for (const child of inner.get(at)?.values() ?? []) stack.push(child);
  }
  return false;
}

/**
 * @param {any} ast
 * @returns {string}
 */
function printFlowchart(ast) {
  const out = ['flowchart ' + (ast.direction || 'TB')];

  // 1. Every node declared once, in AST order — this fixes node order
  //    on the round trip. Default nodes emit a bare id line.
  for (const node of ast.nodes) {
    out.push(nodeDecl(node));
  }

  // 2. Subgraphs: reference members by bare id (membership only); a member
  //    that names another subgraph is that subgraph, written inside this one
  const inner = nestedSubgraphs(ast);
  const printSubgraph = (/** @type {any} */ sg, /** @type {string} */ indent) => {
    out.push(indent + (sg.label && sg.label !== ''
      ? `subgraph ${RE_SUBGRAPH_ID_NEEDS_QUOTE.test(sg.id) ? `"${sg.id}"` : sg.id} [${labelSource(sg.label, RE_TITLE_NEEDS_QUOTE)}]`
      : `subgraph ${sg.id}`));
    if (sg.direction) out.push(indent + '  direction ' + sg.direction);
    for (const id of sg.nodes) {
      const child = inner.get(sg)?.get(id);
      if (child === undefined) out.push(indent + '  ' + id);
      else printSubgraph(child, indent + '  ');
    }
    out.push(indent + 'end');
  };
  const nested = new Set([...inner.values()].flatMap((children) => [...children.values()]));
  for (const sg of ast.subgraphs) if (!nested.has(sg)) printSubgraph(sg, '');

  // 3. Edges in AST order.
  for (const e of ast.edges) {
    const op = edgeOp(e);
    const label = e.label != null ? `|${labelSource(e.label, RE_EDGE_NEEDS_QUOTE)}|` : '';
    out.push(`${e.from} ${op}${label} ${e.to}`);
  }

  // 4. classDef / class / style, each in AST order.
  for (const cd of ast.classDefs) out.push(`classDef ${cd.name} ${cd.styles}`);
  for (const c of ast.classes) out.push(`class ${c.node} ${c.name}`);
  for (const s of ast.styles) out.push(`style ${s.node} ${s.styles}`);

  // 5. click statements in AST order; a tree written before they were read
  //    has no `clicks`
  for (const click of ast.clicks ?? []) out.push(printNodeClick(click));

  return out.join('\n') + '\n';
}

/**
 * @param {any} node
 * @returns {string}
 */
function nodeDecl(node) {
  if (node.shape === 'rect' && node.label === node.id) return node.id;
  if (!FLOW_NAMED_SHAPES.has(node.shape)) return node.id + wrapShape(node.shape, node.label);
  // a shape with no bracket form is named by its metadata, after the label
  // in brackets where the label is not the id (`A["x"]@{ shape: doc }`)
  return node.id + (node.label === node.id ? '' : wrapShape('rect', node.label)) + `@{ shape: ${node.shape} }`;
}

/**
 * Each bracket shape's opening and closing delimiters; a shape only metadata
 * names prints as metadata (`nodeDecl`), and any other as a rectangle.
 */
const SHAPE_DELIMITERS = /** @type {Record<string, [string, string]>} */ ({
  round: ['(', ')'],
  stadium: ['([', '])'],
  subroutine: ['[[', ']]'],
  cylinder: ['[(', ')]'],
  circle: ['((', '))'],
  doublecircle: ['(((', ')))'],
  diamond: ['{', '}'],
  hexagon: ['{{', '}}'],
  parallelogram: ['[/', '/]'],
  parallelogram_alt: ['[\\', '\\]'],
  trapezoid: ['[/', '\\]'],
  trapezoid_alt: ['[\\', '/]'],
  asymmetric: ['>', ']'],
});

/**
 * @param {string} shape
 * @param {string} label
 * @returns {string}
 */
function wrapShape(shape, label) {
  const [open, close] = Object.hasOwn(SHAPE_DELIMITERS, shape) ? SHAPE_DELIMITERS[shape] : ['[', ']'];
  return open + labelSource(label, RE_NEEDS_QUOTE) + close;
}

/**
 * Reconstruct the canonical link operator (the exact inverse of
 * `classifyLink` in the parser).
 * @param {any} e
 * @returns {string}
 */
function edgeOp(e) {
  const tail = e.tail === 'arrow' ? '<' : e.tail === 'circle' ? 'o' : e.tail === 'cross' ? 'x' : '';
  const head = e.head === 'arrow' ? '>' : e.head === 'circle' ? 'o' : e.head === 'cross' ? 'x' : '';
  const n = Math.max(1, e.length | 0);
  let mid;
  if (e.stroke === 'invisible') return '~'.repeat(Math.max(3, n));
  if (e.stroke === 'thick') mid = '='.repeat(n);
  else if (e.stroke === 'dotted') mid = '-' + '.'.repeat(n) + '-';
  else mid = '-'.repeat(Math.max(2, n));
  return tail + mid + head;
}

//#endregion
//#region sequence --------------------------------------------------

/**
 * @param {any} ast
 * @returns {string}
 */
function printSequence(ast) {
  const out = ['sequenceDiagram'];
  if (ast.autonumber) out.push('autonumber');
  for (const p of ast.participants) {
    const decl = p.kind === 'actor' ? 'actor' : 'participant';
    const type = p.type == null ? '' : `@{ "type": "${p.type}" }`;
    out.push(p.label === p.id ? `${decl} ${p.id}${type}` : `${decl} ${p.id}${type} as ${semicolonsCoded(p.label)}`);
  }
  printSeqStatements(ast.statements, out, 0);
  return out.join('\n') + '\n';
}

/**
 * @param {any[]} statements
 * @param {string[]} out
 * @param {number} depth
 */
function printSeqStatements(statements, out, depth) {
  const pad = '  '.repeat(depth);
  for (const stmt of statements) {
    if (stmt.kind === 'message') {
      const arrow = arrowToken(stmt.line, stmt.head);
      const act = stmt.activation === 'activate' ? '+' : stmt.activation === 'deactivate' ? '-' : '';
      const fromMark = stmt.central === 'from' || stmt.central === 'both' ? '()' : '';
      const toMark = stmt.central === 'to' || stmt.central === 'both' ? '()' : '';
      out.push(`${pad}${stmt.from}${fromMark}${arrow}${act}${toMark}${stmt.to}: ${semicolonsCoded(stmt.text)}`);
    }
    else if (stmt.kind === 'note') {
      out.push(`${pad}note ${stmt.placement} ${stmt.actors.join(',')}: ${semicolonsCoded(stmt.text)}`);
    }
    else if (stmt.kind === 'activate' || stmt.kind === 'deactivate') {
      out.push(`${pad}${stmt.kind} ${stmt.actor}`);
    }
    else if (stmt.kind === 'block') {
      const branchWord = stmt.blockType === 'par' ? 'and'
        : stmt.blockType === 'critical' ? 'option' : 'else';
      const b0 = stmt.branches[0];
      out.push(`${pad}${stmt.blockType}${b0.label ? ' ' + semicolonsCoded(b0.label) : ''}`);
      printSeqStatements(b0.statements, out, depth + 1);
      for (let i = 1; i < stmt.branches.length; i++) {
        const b = stmt.branches[i];
        out.push(`${pad}${branchWord}${b.label ? ' ' + semicolonsCoded(b.label) : ''}`);
        printSeqStatements(b.statements, out, depth + 1);
      }
      out.push(`${pad}end`);
    }
  }
}

/**
 * A line that reads back as one statement: a `;` in its text prints as
 * `#59;`, which the drawing decodes, only where the line would otherwise
 * split into statements or end its statement early (a state's description
 * or transition label, MERMAID-FORMAT §4.3).
 * @param {string} head - the statement up to its text
 * @param {string} text
 * @param {(line: string) => string[]} statements - the type's statement splitter
 * @returns {string}
 */
function oneStatement(head, text, statements) {
  const line = head + text;
  const read = statements(line.trim());
  return read.length === 1 && read[0] === line.trim() ? line : head + semicolonsCoded(text);
}

/**
 * Text whose every `;` prints as `#59;`, which the drawing decodes, an
 * entity code it holds kept: Mermaid refuses a `;` in a sequence message,
 * note, block label or participant alias and in a class relation label or
 * `Name : member` line.
 * @param {string} text
 * @returns {string}
 */
function semicolonsCoded(text) {
  return text.replace(/(#[A-Za-z0-9]+;)|;/g, (m, code) => code ?? '#59;');
}

/** Each half-arrow head's marks, written after the line or (`-reverse`) before it. */
const HALF_HEAD_MARKS = /** @type {Record<string, string>} */ ({
  __proto__: null,
  'half-top': '|\\', 'half-bottom': '|/', 'stick-top': '\\\\', 'stick-bottom': '//',
  'half-top-reverse': '/|', 'half-bottom-reverse': '\\|', 'stick-top-reverse': '//', 'stick-bottom-reverse': '\\\\',
});

/**
 * The exact inverse of `classifyArrow`.
 * @param {'solid'|'dotted'} line
 * @param {import('./ast.js').SeqHead} head
 * @returns {string}
 */
function arrowToken(line, head) {
  const dash = line === 'dotted' ? '--' : '-';
  if (head === 'both') return `<<${dash}>>`;
  const marks = HALF_HEAD_MARKS[head];
  if (marks !== undefined) return head.endsWith('-reverse') ? marks + dash : dash + marks;
  const tip = head === 'arrow' ? '>>' : head === 'cross' ? 'x' : head === 'point' ? ')' : '>';
  return dash + tip;
}

//#endregion
//#region class / state / er / gantt / pie (best effort) ------------

/**
 * Can this class member not stand on a line of a `{ … }` body?
 * @param {{ visibility: string|null, text: string }} member
 * @returns {boolean}
 */
function isUnbracedMember(member) {
  return member.text.includes('}') || (member.visibility === null && member.text.startsWith('%%'));
}

/** A class name only words spell, which is written bare. */
const RE_BARE_CLASS = /^[^\s"`:;<>*|()\-[\]{}~]+$/;

/** A bare word Mermaid's class lexer reads as a keyword, not as a name (`note`, `link`, `_self`). */
const RE_BARE_KEYWORD = /^(?:cssClass|callback|link|click|note|href|_self|_blank|_parent|_top)\b/;

/** A generic written bare after a bare name: words and entity codes (`#lt;`), its nesting written as codes. */
const RE_BARE_GENERIC = /^[^\s"`:;<>*|()\-[\]{}]+$/;

/**
 * A class name as it is written between backticks: each `~` as `#126;`
 * (Mermaid splits a backtick name at its `~`s) and a first character
 * Mermaid's lexer reads as syntax there (`note`, `<<`, a `"`) as its entity
 * code, both of which the drawing decodes.
 * @param {string} name
 * @returns {string}
 */
function backtickClassName(name) {
  const text = name.replaceAll('~', '#126;');
  const lead = RE_BACKTICK_KEYWORD.exec(text);
  if (lead === null) return text;
  // `<<` and `>>` are two characters of syntax, a keyword is one word
  const coded = lead[0] === '<<' || lead[0] === '>>' ? 2 : 1;
  return [...text.slice(0, coded)].map((c) => `#${c.codePointAt(0)};`).join('') + text.slice(coded);
}

/** An entity code, which Mermaid reads before it reads a line. */
const RE_ENTITY_CODE = /#\w+;/g;

/**
 * @param {any} ast
 * @returns {string}
 */
function printClass(ast) {
  const out = ['classDiagram'];
  // a name only words may spell is written bare; any other in backticks
  const bare = (/** @type {string} */ n) => RE_BARE_CLASS.test(n) && !RE_BARE_KEYWORD.test(n);
  const name = (/** @type {string} */ n) => (bare(n) ? n : `\`${backtickClassName(n)}\``);
  for (const cls of ast.classes) {
    // a generic follows its name, both inside the backticks of a quoted
    // one; a generic it nests is written with `#lt;`/`#gt;`, which no reader
    // splits the name at and both draw nested (Mermaid reads
    // `Grid~List~int~~` as no class, and `` `Grid~List~int~~` `` as `Grid` of
    // `List`)
    const generic = cls.generic == null ? null : genericText(cls.generic, '#lt;', '#gt;');
    const written = generic === null ? name(cls.name)
      : bare(cls.name) && RE_BARE_GENERIC.test(generic.replace(RE_ENTITY_CODE, '')) ? `${cls.name}~${generic}~`
        : `\`${backtickClassName(cls.name)}~${generic}~\``;
    const head = `class ${written}${cls.label !== cls.name ? `[${inQuotes(cls.label)}]` : ''}`;
    // an annotation is a body line, which takes any text but the `}` that
    // ends the body (written as its code)
    const annotations = (cls.annotations ?? []).map((/** @type {string} */ a) => `  <<${a.replaceAll('}', '#125;')}>>`);
    if (cls.members.length === 0 && annotations.length === 0) {
      out.push(head);
    }
    else if (cls.members.some(isUnbracedMember)) {
      // a body ends at its first `}` and drops comment-looking lines, so
      // such a member can only be written as a `Name : member` line
      out.push(...(annotations.length === 0 ? [head] : [`${head} {`, ...annotations, '}']));
      // and a `;` there is refused, so it prints as its code
      for (const m of cls.members) out.push(`${cls.name} : ${semicolonsCoded(`${m.visibility ?? ''}${m.text}`)}`);
    }
    else {
      out.push(`${head} {`, ...annotations);
      for (const m of cls.members) out.push(`  ${m.visibility ?? ''}${m.text}`);
      out.push('}');
    }
  }
  for (const r of ast.relations) {
    const fromCard = r.fromCardinality === undefined ? '' : ` ${inQuotes(r.fromCardinality)}`;
    const toCard = r.toCardinality === undefined ? '' : `${inQuotes(r.toCardinality)} `;
    out.push(`${name(r.from)}${fromCard} ${r.type} ${toCard}${name(r.to)}${r.label ? ' : ' + semicolonsCoded(r.label) : ''}`);
  }
  for (const click of ast.clicks ?? []) out.push(printNodeClick(click));
  return out.join('\n') + '\n';
}

/**
 * Print a state diagram. The states keep the order the AST lists them in
 * (layout reads it); when the plain spelling would introduce them in
 * another order — a labelled state used before its label line, a child
 * listed before its parent — every state is declared up front instead.
 * @param {any} ast
 * @returns {string}
 */
function printState(ast) {
  const text = printStateLines(ast, false);
  if (sameStates(text, ast)) return text;
  const declared = printStateLines(ast, true);
  return sameStates(declared, ast) ? declared : text;
}

/**
 * Does this printed diagram introduce the AST's states in the AST's order?
 * @param {string} text
 * @param {any} ast
 * @returns {boolean}
 */
function sameStates(text, ast) {
  const read = /** @type {any} */ (parseState(text.split('\n').slice(1)));
  return read.states.length === ast.states.length
    && read.states.every((/** @type {any} */ s, /** @type {number} */ i) => s.id === ast.states[i].id);
}

/**
 * A labelled state's line: `X : label`, or `state "label" as X` for a label
 * holding a `;`, which would end the `:` form's label there.
 * @param {{ id: string, label: string }} s
 * @returns {string}
 */
function stateLabelLine(s) {
  return s.label.includes(';') && !/["\n]/.test(s.label) ? `state "${s.label}" as ${s.id}`
    : oneStatement(`${s.id} : `, s.label, stateStatements);
}

/**
 * One transition's line, read back as the one transition it is.
 * @param {any} t
 * @returns {string}
 */
function transitionLine(t) {
  return t.label ? oneStatement(`${t.from} --> ${t.to} : `, t.label, stateStatements) : `${t.from} --> ${t.to}`;
}

/**
 * @param {any} ast
 * @param {boolean} declareAll declare every state at the top level first
 * @returns {string}
 */
function printStateLines(ast, declareAll) {
  const out = ['stateDiagram-v2'];
  const nested = ast.states.some((s) => s.parent != null) || ast.transitions.some((t) => t.parent != null);
  if (declareAll) {
    for (const s of ast.states) out.push(s.label !== s.id ? stateLabelLine(s) : stateDeclaration(s.id));
  }
  if (nested) {
    const states = new Map(ast.states.map((s) => [s.id, s]));
    let opened = [];
    const scope = (parent) => {
      const target = [];
      for (let id = parent; id != null; id = states.get(id)?.parent) {
        if (target.includes(id)) throw new TypeError('cyclic state-diagram parent');
        target.unshift(id);
      }
      let shared = 0;
      while (shared < opened.length && opened[shared] === target[shared]) shared++;
      for (let i = opened.length; i > shared; i--) out.push('  '.repeat(i - 1) + '}');
      for (let i = shared; i < target.length; i++) out.push('  '.repeat(i) + `state ${target[i]} {`);
      opened = target;
    };
    // Declare every id first, then retain transition document order even
    // when that requires reopening a compound scope. Priority survives print.
    for (const s of ast.states) {
      // a state declared up front is moved under its parent by naming it there
      if (declareAll && s.parent == null) continue;
      scope(s.parent);
      out.push('  '.repeat(opened.length)
        + (declareAll || s.label === s.id ? stateDeclaration(s.id) : stateLabelLine(s)));
    }
    for (const t of ast.transitions) {
      scope(t.parent);
      out.push('  '.repeat(opened.length) + transitionLine(t));
    }
    scope(null);
    return out.join('\n') + '\n';
  }
  if (!declareAll) {
    // an id-only state no transition mentions must still be DECLARED, or
    // the canonical round trip silently drops it (its name on a line of
    // its own, which Mermaid reads too, or `state x` where that would not
    // read back)
    const mentioned = new Set();
    for (const t of ast.transitions) {
      mentioned.add(t.from);
      mentioned.add(t.to);
    }
    for (const s of ast.states) {
      if (s.label !== s.id) out.push(stateLabelLine(s));
      else if (!mentioned.has(s.id)) out.push(stateDeclaration(s.id));
    }
  }
  for (const t of ast.transitions) {
    out.push(transitionLine(t));
  }
  return out.join('\n') + '\n';
}

/**
 * A label Mermaid reads as one word, which prints bare: its word characters
 * (letters, digits, `_`, `-`, `*`, `.`, any non-ASCII one), opening with no
 * digit and no keyword of its lexer (`one`, `many`, `to`, `class`, `u-`).
 */
const RE_ER_BARE_LABEL = /^(?![0-9])(?!(?:one|many|to|class|classdef|style|erdiagram)\b|u[.-])[\w*.\u0080-\uffff-]+$/i;

/**
 * A relationship label as Mermaid reads it: one word (`RE_ER_BARE_LABEL`) as
 * it stands, anything else (more than one word, a quote, nothing at all) in
 * quotes (`inQuotes`), as Mermaid reads only one word or one quoted string
 * as the label, so a coded label prints as it did when it held the quote.
 * @param {string} label
 * @returns {string}
 */
function erLabel(label) {
  return RE_ER_BARE_LABEL.test(label) ? label : inQuotes(label);
}

/**
 * @param {any} ast
 * @returns {string}
 */
function printEr(ast) {
  const out = ['erDiagram'];
  // a name with a space must be quoted to read back as one name, and one
  // with a quote is quoted with the quote as its code (a `;` quoted too, so
  // a coded name prints as it did when it held the quote)
  const name = (/** @type {string} */ n) => (/[\s";]/.test(n) ? inQuotes(n) : n);
  for (const e of ast.entities) {
    const head = name(e.name) + (e.alias === undefined ? '' : /^[^\s"\];]+$/.test(e.alias) ? `[${e.alias}]` : `[${inQuotes(e.alias)}]`);
    if (e.attributes.length === 0) { out.push(head); continue; }
    out.push(`${head} {`);
    for (const a of e.attributes) {
      out.push(`  ${a.type} ${a.name}${a.keys.length ? ' ' + a.keys.join(', ') : ''}${a.comment === undefined ? '' : ` ${inQuotes(a.comment)}`}`);
    }
    out.push('}');
  }
  for (const r of ast.relationships) {
    out.push(`${name(r.left)} ${r.leftCard}${r.identifying ? '--' : '..'}${r.rightCard} ${name(r.right)} : ${erLabel(r.label)}`);
  }
  return out.join('\n') + '\n';
}

/**
 * @param {any} ast
 * @returns {string}
 */
function printGantt(ast) {
  const out = ['gantt'];
  for (const key of Object.keys(ast.meta)) out.push(`${key} ${ast.meta[key]}`.trim());
  for (const section of ast.sections) {
    if (section.name) out.push(`section ${section.name}`);
    for (const t of section.tasks) out.push(`${t.name} : ${t.info}`);
  }
  // a tree written before `click` existed has no `clicks`
  for (const click of ast.clicks ?? []) out.push(printClick(click));
  return out.join('\n') + '\n';
}

/**
 * @param {any} ast
 * @returns {string}
 */
function printPie(ast) {
  const out = ['pie' + (ast.showData ? ' showData' : '')];
  if (ast.title) out.push('title ' + ast.title);
  for (const s of ast.slices) {
    // the reader decodes a slice's entity codes, so a `#` that would open one
    // is written as its code `#35;`
    const label = s.label.replace(/\n/g, '<br/>').replace(RE_CODE_HASH, '#35;');
    // a label holding a `"` (and no `'`) is written in `'…'`, which Mermaid
    // reads; one holding both kinds in `"…"`, each `"` as its code `#34;`
    // (Mermaid has no escape inside the quotes)
    const quoted = label.includes('"') && !label.includes("'") ? `'${label}'` : inQuotes(label);
    out.push(`${quoted} : ${plainDecimal(s.value)}`);
  }
  return out.join('\n') + '\n';
}

/** A `#` that opens an entity code (`#34;`, `#quot;`). */
const RE_CODE_HASH = /#(?=\w+;)/g;

/**
 * A number as the plain decimal a pie row reads (`1e-7` is not one).
 * @param {number} value
 * @returns {string}
 */
function plainDecimal(value) {
  if (value < 0) return '-' + plainDecimal(-value);
  const text = String(value);
  const at = text.indexOf('e');
  if (at === -1) return text;
  const [whole, fraction = ''] = text.slice(0, at).split('.');
  const digits = whole + fraction;
  const point = whole.length + Number(text.slice(at + 1));
  if (point <= 0) return '0.' + '0'.repeat(-point) + digits;
  return point >= digits.length
    ? digits + '0'.repeat(point - digits.length)
    : digits.slice(0, point) + '.' + digits.slice(point);
}

