//@ts-check

import {
  isArrayClass,
  isMapClass,
  getObjectType,
} from '@jarenjs/core';

import {
  getIntishType,
} from '@jarenjs/core/number';

import { createSchemaPatternTester } from './string.js';
import { readsSince } from './schema-keywords.js';
import { nameErrorRecords } from './messages.js';

import {
  trueThat,
} from '@jarenjs/core/function';

import {
  annotatesFailedMembers,
  getBoolOrObjectClass,
  getArrayClassMinItems,
  isOfSchemaType,
  ValidationResult,
  memberPath,
  extendsChildLocations,
  OBJECT_CHILD_KEYWORDS,
  otherKind,
  isObjectInstance,
  isTypeOnlyString,
  isTypeOnlyNumber,
  isTypeOnlyInteger,
  isTypeOnlyBoolean,
  isTypeOnlyArray,
  isTypeOnlyObject,
  isTypeOnlyNull,
} from './tools.js';

// An own member Object.keys does not list (a non-enumerable one) is present
// to `required`, to the names `dependentRequired` and a `dependencies` list
// require, and as the trigger of a dependency keyword, as a listed member
// is: those readers probe with Object.hasOwn. An inherited member is absent
// to them. `minProperties` and `maxProperties` count the members Object.keys
// lists, and the walks over those members (`additionalProperties`,
// `patternProperties`, `propertyNames`, and `properties` wherever it does not
// read by a probe, see readsNamedMembers) read the listed members only.

/**
 * Whether `key` is no own member of data, for a closure that holds
 * `dataKeys`, the members Object.keys listed, for a count: a listed member
 * is an own member, so the list answers for it, and a name it does not hold
 * is absent only when Object.hasOwn says so (an own member Object.keys does
 * not list is present).
 * @param {object} data
 * @param {string[]} dataKeys
 * @param {string} key
 * @returns {boolean}
 */
function isAbsentMember(data, dataKeys, key) {
  return dataKeys.indexOf(key) === -1 && !Object.hasOwn(data, key);
}

/**
 * Whether every name is an own member of data: what `dependentRequired` and
 * a `dependencies` list require once their trigger is there, and the member
 * walks' `required` names a walk over the listed members did not meet.
 * @param {object} data
 * @param {string[]} names
 * @returns {boolean}
 */
function hasOwnAll(data, names) {
  for (let i = 0; i < names.length; ++i) {
    if (!Object.hasOwn(data, names[i])) return false;
  }
  return true;
}

// Object.prototype.hasOwnProperty, called inside a `for…in` over the same
// object, where V8 answers it from the enumeration cache.
const hasOwnProperty = Object.prototype.hasOwnProperty;

/**
 * Whether `key` is an own member of data that the walk over `dataKeys`, the
 * members Object.keys listed, did not go over.
 * @param {object} data
 * @param {string[]} dataKeys
 * @param {string} key
 * @returns {boolean}
 */
function isUnlistedMember(data, dataKeys, key) {
  return Object.hasOwn(data, key) && !dataKeys.includes(key);
}

//#region Primitives
function compileMinProperties(schemaObj, jsonSchema) {
  const min = getIntishType(jsonSchema.minProperties) || 0;
  if (min < 1) return undefined;

  const addError = schemaObj.createErrorHandler(min, 'minProperties');
  return function validateMinProperties(len = 0, dataPath = '') {
    return len >= min || addError(len, dataPath);
  };
}

function compileMaxProperties(schemaObj, jsonSchema) {
  const max = getIntishType(jsonSchema.maxProperties);
  if (max == null || max < 0) return undefined;

  const addError = schemaObj.createErrorHandler(max, 'maxProperties');
  return function validateMaxProperties(len = 0, dataPath = '') {
    return len <= max || addError(len, dataPath);
  };
}

function compileRequiredProperties(schemaObj, jsonSchema) {
  const required = getArrayClassMinItems(jsonSchema.required, 1);
  if (required == null) return undefined;

  const rlength = required.length;
  /** @type {function(string, any, string):boolean} */
  // Use array key to get keyed error handler: addKeyedError(dataKey, data, ...meta)
  const addError = schemaObj.createErrorHandler(required, ['required']);
  // When errors are recorded, every missing property must produce one; only
  // the boolean-answer path may stop at the first.
  const stopAtFirst = schemaObj.root.options.skipErrors;
  return function validateRequiredProperties(data = {}, dataKeys = [], dataPath = '') {
    // (no listed member: the `minProperties` this stands beside has failed
    // and reported)
    if (!(dataKeys.length > 0))
      return false;

    let valid = true;
    for (let i = 0; i < rlength; ++i) {
      const key = required[i];
      // (a listed member is an own member, see isAbsentMember)
      if (isAbsentMember(data, dataKeys, key)) {
        valid = addError(key, data, dataPath) && valid;
        if (stopAtFirst) break;
      }
    }
    return valid;
  };
}
//#endregion

//#region Constraints
function compilePropertyNames(schemaObj, jsonSchema) {
  const propNames = getBoolOrObjectClass(jsonSchema.propertyNames);
  if (propNames == null) return undefined;

  const propertyNamesValidator = schemaObj.createValidator(propNames, 'propertyNames');
  // The property NAME is the validated data; the object's data path is
  // threaded through so name failures report a usable instancePath: the
  // name is no instance, so they fail at the object.
  if (schemaObj.options.skipErrors) {
    return function validatePropertyNames(dataKey, dataPath) {
      return propertyNamesValidator(dataKey, dataPath);
    };
  }
  // Errors are kept: each one the name raised names it in its params
  // (`propertyName`), as an `additionalProperties` error names its member.
  const root = schemaObj.root;
  return function validateNamedPropertyNames(dataKey, dataPath) {
    const from = root.errorMark();
    const valid = propertyNamesValidator(dataKey, dataPath);
    if (valid === false) nameErrorRecords(root.errors, from, dataKey);
    return valid;
  };
}

function buildPropertyValidators(schemaObj, jsonSchema) {
  const properties = getObjectType(jsonSchema.properties);
  if (properties == null) return undefined;

  // Use Object.getOwnPropertyNames to handle __proto__ correctly
  // Object.keys() doesn't return __proto__ when defined via { __proto__: value }
  const keys = Object.getOwnPropertyNames(properties);
  if (keys.length === 0) return undefined;

  const validators = new Map();
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const schemas = properties[key];
    const validator = schemaObj.createValidator(schemas, 'properties', key);
    if (validator != null)
      validators.set(key, validator);
  }
  if (validators.size === 0)
    return undefined;

  return validators;
}

function compileProperties(schemaObj, jsonSchema) {
  const validators = buildPropertyValidators(schemaObj, jsonSchema);
  if (validators == null) return undefined;

  const root = schemaObj.root;
  const track = root.usesUnevaluated;
  const logFailed = annotatesFailedMembers(schemaObj);

  return function validatePropertyItem(data, dataPath, dataRoot, dataKey) {
    const result = new ValidationResult();
    const validator = validators.get(dataKey);
    if (validator == null)
      return result;
    else {
      const valid = validator(data[dataKey], dataPath, dataRoot, dataKey);
      if (track && (valid === true || logFailed)) root.evalLog.add(data, dataKey);
      return result.addMatch(valid);
    }
  };
}

function buildPatternValidators(schemaObj, jsonSchema) {
  const entries = getObjectType(jsonSchema.patternProperties);
  if (entries == null) return undefined;

  // Use Object.getOwnPropertyNames to handle __proto__ correctly
  const entryKeys = Object.getOwnPropertyNames(entries);
  if (entryKeys.length === 0) return undefined;

  const list = [];
  for (let i = 0; i < entryKeys.length; ++i) {
    const key = entryKeys[i];
    const matches = createSchemaPatternTester(key);
    if (matches == null) continue;

    const validator = schemaObj.createValidator(entries[key], 'patternProperties', key);
    if (validator != null)
      list.push({ matches, validator });
  }

  if (list.length === 0) return undefined;

  return list;
}

function compilePatternProperties(schemaObj, jsonSchema) {
  const list = buildPatternValidators(schemaObj, jsonSchema);
  if (list == null) return undefined;

  const root = schemaObj.root;
  const track = root.usesUnevaluated;
  const logFailed = annotatesFailedMembers(schemaObj);

  return function validatePatternPropertiesItem(data, dataPath, dataRoot, dataKey) {
    const result = new ValidationResult();
    for (let i = 0; i < list.length; ++i) {
      const { matches, validator } = list[i];
      if (matches(dataKey)) {
        const valid = validator(data[dataKey], dataPath, dataRoot, dataKey);
        if (track && (valid === true || logFailed)) root.evalLog.add(data, dataKey);
        result.addMatch(valid);
      }
    }
    return result;
  };
}

function compileAdditionalProperties(schemaObj, jsonSchema) {
  const additional = getBoolOrObjectClass(jsonSchema.additionalProperties);
  if (additional == null) return undefined;

  const root = schemaObj.root;
  const track = root.usesUnevaluated;
  const logFailed = annotatesFailedMembers(schemaObj);

  if (additional === false) {
    const addError = schemaObj.createErrorHandler(false, ['additionalProperties']);

    return function validateNoAdditionalProperties(data, dataPath, dataRoot, dataKey) {
      if (track && logFailed) root.evalLog.add(data, dataKey);
      return addError(dataKey, data, dataPath);
    };
  }

  const validator = schemaObj.createValidator(additional, 'additionalProperties');

  return function validateAdditionalPropertyItem(data, dataPath, dataRoot, dataKey) {
    const valid = validator(data[dataKey], dataPath, dataRoot, dataKey);
    if (track && (valid === true || logFailed)) root.evalLog.add(data, dataKey);
    return valid;
  };
}
//#endregion

//#region Dependencies
function compileDependentRequired(schemaObj, jsonSchema) {
  if (!readsSince('dependentRequired', schemaObj.declaredDraft))
    return undefined;

  const dependentRequired = getObjectType(jsonSchema.dependentRequired);
  if (dependentRequired == null)
    return undefined;

  if (Object.keys(dependentRequired).length === 0)
    return undefined;

  // Keyed handler: addError(dataKey, data, ownerPath) - dataKey names the
  // triggering property, rest[0] is the object's location: the keyword
  // asserts which members the object holds, so it fails at the object (as
  // `required` does).
  const addError = schemaObj.createErrorHandler(false, ['dependentRequired']);

  return function validateDependentRequiredItem(data, dataPath, dataRoot, dataKey, ownerPath = dataPath) {
    if (Object.hasOwn(dependentRequired, dataKey)) {
      const required = dependentRequired[dataKey];
      return hasOwnAll(data, required)
        || addError(dataKey, data, ownerPath);
    }
    return true;
  };
}

function compileDependentSchemas(schemaObj, jsonSchema) {
  if (!readsSince('dependentSchemas', schemaObj.declaredDraft))
    return undefined;

  const dependentSchemas = getObjectType(jsonSchema.dependentSchemas);
  if (dependentSchemas == null) return undefined;

  // every member is a schema: another value is refused before this compiles
  const validators = new Map();
  for (const key in dependentSchemas) {
    if (Object.hasOwn(dependentSchemas, key))
      validators.set(key, schemaObj.createValidator(dependentSchemas[key], 'dependentSchemas', key));
  }

  if (validators.size === 0)
    return undefined;

  // The dependent schema applies to the object that holds the trigger
  // member, so it is handed the object's own location (`ownerPath`), not
  // the member's: what it reports and what a relative `$data` reference
  // inside it resolves against is the object.
  return function validateDependentSchemasItem(data, dataPath, dataRoot, dataKey, ownerPath = dataPath) {
    if (validators.has(dataKey)) {
      const validator = validators.get(dataKey);
      return validator(data, ownerPath, dataRoot, dataKey);
    }
    return true;
  };
}

function compileDependencies(schemaObj, jsonSchema) {
  const dependencies = getObjectType(jsonSchema.dependencies);
  if (dependencies == null)
    return undefined;

  // Collect dependency entries into arrays for faster access
  const depKeys = Object.keys(dependencies);
  if (depKeys.length === 0)
    return undefined;

  // Separate schema dependencies from required dependencies for optimization
  const schemaDeps = [];
  const requiredDeps = [];

  // every member is a schema or a list of names: another value is refused
  // before this compiles
  for (let i = 0; i < depKeys.length; i++) {
    const key = depKeys[i];
    const right = dependencies[key];
    if (isArrayClass(right)) {
      const addError = schemaObj.createErrorHandler(right, ['dependencies']);
      requiredDeps.push({ key, required: right, addError });
    }
    else
      schemaDeps.push({ key, validator: schemaObj.createValidator(right, 'dependencies', key) });
  }

  if (schemaDeps.length === 0 && requiredDeps.length === 0)
    return undefined;

  // Single schema dependency - most common case
  if (schemaDeps.length === 1 && requiredDeps.length === 0) {
    const { key, validator } = schemaDeps[0];
    return function validateSingleSchemaDep(data, dataPath, dataRoot, dataKey, ownerPath = dataPath) {
      if (dataKey === key) {
        return validator(data, ownerPath, dataRoot, dataKey);
      }
      return true;
    };
  }

  // Single required dependency - common case
  if (requiredDeps.length === 1 && schemaDeps.length === 0) {
    const { key, required, addError } = requiredDeps[0];
    // A list asserts which members the object holds: it fails at the object.
    return function validateSingleRequiredDep(data, dataPath, dataRoot, dataKey, ownerPath = dataPath) {
      return dataKey !== key
        || hasOwnAll(data, required)
        || addError(dataKey, data, ownerPath);
    };
  }

  // Multiple dependencies - generic case
  // Create lookup maps for faster access
  const schemaDepMap = new Map();
  for (let i = 0; i < schemaDeps.length; i++) {
    schemaDepMap.set(schemaDeps[i].key, schemaDeps[i].validator);
  }
  const requiredDepMap = new Map();
  for (let i = 0; i < requiredDeps.length; i++) {
    requiredDepMap.set(requiredDeps[i].key, requiredDeps[i]);
  }

  return function validateDependenciesItem(data, dataPath, dataRoot, dataKey, ownerPath = dataPath) {
    // Check schema dependencies first
    const schemaValidator = schemaDepMap.get(dataKey);
    if (schemaValidator != null) {
      return schemaValidator(data, ownerPath, dataRoot, dataKey);
    }
    // Check required dependencies
    const reqDep = requiredDepMap.get(dataKey);
    if (reqDep != null) {
      const { required, addError } = reqDep;
      return hasOwnAll(data, required)
        || addError(dataKey, data, ownerPath);
    }
    return true;
  };
}

/**
 * The member names that trigger one of a schema's compiled dependency
 * keywords, each once: every name one of those validators answers for (the
 * own names of `dependentRequired`, the listed ones of the other two). The
 * walks hand the keywords each listed member that is one of them, then
 * probe the names they did not meet for an own member Object.keys does not
 * list.
 * @param {object} jsonSchema
 * @param {Function | null | undefined} depRequired - The compiled `dependentRequired`
 * @param {Function | null | undefined} depSchemas - The compiled `dependentSchemas`
 * @param {Function | null | undefined} dependencies - The compiled `dependencies`
 * @returns {string[]}
 */
function dependencyTriggers(jsonSchema, depRequired, depSchemas, dependencies) {
  const names = new Set();
  if (depRequired != null) for (const key of Object.getOwnPropertyNames(jsonSchema.dependentRequired)) names.add(key);
  if (depSchemas != null) for (const key of Object.keys(jsonSchema.dependentSchemas)) names.add(key);
  if (dependencies != null) for (const key of Object.keys(jsonSchema.dependencies)) names.add(key);
  return Array.from(names);
}

/**
 * Whether a schema's object keywords are `properties` with at most a
 * `required` list and `additionalProperties`: the shape the member walks of
 * the first-failure mode take (compilePropertiesWalk).
 * @param {object} jsonSchema
 * @returns {boolean}
 */
function holdsPropertiesOnly(jsonSchema) {
  return jsonSchema.patternProperties == null
    && jsonSchema.propertyNames == null
    && jsonSchema.dependencies == null
    && jsonSchema.dependentSchemas == null
    && jsonSchema.dependentRequired == null
    && jsonSchema.minProperties == null
    && jsonSchema.maxProperties == null
    && (jsonSchema.required == null || isArrayClass(jsonSchema.required))
    && getObjectType(jsonSchema.properties) != null;
}

/**
 * Whether a schema's `properties` reads each member it names by a probe of
 * its own (Object.hasOwn), in both modes, so that an own member Object.keys
 * does not list is read too: where the schema holds no other object keyword
 * than a `required` list. Beside a keyword that walks or counts the listed
 * members, `properties` reads the listed members only.
 * @param {object} jsonSchema
 * @returns {boolean}
 */
function readsNamedMembers(jsonSchema) {
  return jsonSchema.additionalProperties == null && holdsPropertiesOnly(jsonSchema);
}
//#endregion

//#region Main
export function compileObjectPrimitives(schemaObj, jsonSchema) {
  // minProperties/maxProperties/required belong to the validation
  // vocabulary; assert nothing when the metaschema disables it.
  if (schemaObj.options.vocabValidation === false)
    return undefined;

  const minProperties = compileMinProperties(schemaObj, jsonSchema);
  const maxProperties = compileMaxProperties(schemaObj, jsonSchema);
  const requiredProperties = compileRequiredProperties(schemaObj, jsonSchema);

  if ((minProperties
    || maxProperties
    || requiredProperties) == null)
    return undefined;

  // Inline the validation to reduce function call overhead
  const min = getIntishType(jsonSchema.minProperties) || 0;
  const max = getIntishType(jsonSchema.maxProperties);
  const required = getArrayClassMinItems(jsonSchema.required, 1);

  const hasMin = min > 0;
  const hasMax = max != null && max >= 0;
  const hasRequired = required != null && required.length > 0;
  // When errors are recorded, every missing required property must produce
  // one; only the boolean-answer path may stop at the first.
  const stopAtFirst = schemaObj.root.options.skipErrors;

  // Pre-bind error handlers outside the returned function. Every closure
  // below is called behind the object group's own instance test
  // (compileObjectGroup), so none tests the instance again.
  if (hasMin && !hasMax && !hasRequired) {
    const addError = schemaObj.createErrorHandler(min, 'minProperties');
    return function validateMinPropertiesOnly(data, dataPath, dataRoot, dataKeys) {
      const len = dataKeys ? dataKeys.length : Object.keys(data).length;
      return len >= min || addError(len, dataPath);
    };
  }

  if (!hasMin && hasMax && !hasRequired) {
    const addError = schemaObj.createErrorHandler(max, 'maxProperties');
    return function validateMaxPropertiesOnly(data, dataPath, dataRoot, dataKeys) {
      const len = dataKeys ? dataKeys.length : Object.keys(data).length;
      return len <= max || addError(len, dataPath);
    };
  }

  if (hasMin && hasMax && !hasRequired) {
    const addMinError = schemaObj.createErrorHandler(min, 'minProperties');
    const addMaxError = schemaObj.createErrorHandler(max, 'maxProperties');
    return function validateMinMaxProperties(data, dataPath, dataRoot, dataKeys) {
      const len = dataKeys ? dataKeys.length : Object.keys(data).length;
      return (len >= min || addMinError(len, dataPath))
          && (len <= max || addMaxError(len, dataPath));
    };
  }

  // Specialized paths for required properties
  if (!hasMin && !hasMax && hasRequired) {
    const rlength = required.length;
    const addError = schemaObj.createErrorHandler(required, ['required']);
    // every entry is a member name: another entry is refused before this compiles
    return function validateRequiredHasOwn(data, dataPath, _dataRoot, _dataKeys) {
      let valid = true;
      for (let i = 0; i < rlength; ++i) {
        const key = required[i];
        if (!Object.hasOwn(data, key)) {
          valid = addError(key, data, dataPath) && valid;
          if (stopAtFirst) break;
        }
      }
      return valid;
    };
  }

  if (hasMin && !hasMax && hasRequired) {
    const addMinError = schemaObj.createErrorHandler(min, 'minProperties');
    const rlength = required.length;
    const addReqError = schemaObj.createErrorHandler(required, ['required']);
    return function validateMinAndRequired(data, dataPath, dataRoot, dataKeys) {
      const keys = dataKeys || Object.keys(data);
      const len = keys.length;
      // minProperties and required are independent; a short count says
      // nothing about WHICH members are missing, which is the useful half.
      let sizeOk = len >= min || addMinError(len, dataPath);
      if (stopAtFirst && !sizeOk) return false;
      let valid = true;
      for (let i = 0; i < rlength; ++i) {
        const key = required[i];
        if (isAbsentMember(data, keys, key)) {
          valid = addReqError(key, data, dataPath) && valid;
          if (stopAtFirst) break;
        }
      }
      return sizeOk && valid;
    };
  }

  if (!hasMin && hasMax && hasRequired) {
    const addMaxError = schemaObj.createErrorHandler(max, 'maxProperties');
    const rlength = required.length;
    const addReqError = schemaObj.createErrorHandler(required, ['required']);
    return function validateMaxAndRequired(data, dataPath, dataRoot, dataKeys) {
      const keys = dataKeys || Object.keys(data);
      const len = keys.length;
      // maxProperties and required are independent (see the min case).
      let sizeOk = len <= max || addMaxError(len, dataPath);
      if (stopAtFirst && !sizeOk) return false;
      let valid = true;
      for (let i = 0; i < rlength; ++i) {
        const key = required[i];
        if (isAbsentMember(data, keys, key)) {
          valid = addReqError(key, data, dataPath) && valid;
          if (stopAtFirst) break;
        }
      }
      return sizeOk && valid;
    };
  }

  // Generic case with all checks
  const isMinProperties = minProperties || trueThat;
  const isMaxProperties = maxProperties || trueThat;
  const hasRequiredProperties = requiredProperties || trueThat;

  return function validateObjectPrimitives(data, dataPath, dataRoot, dataKeys) {
    const keys = dataKeys || Object.keys(data);
    const len = keys.length;
    if (stopAtFirst) {
      return isMinProperties(len, dataPath)
        && isMaxProperties(len, dataPath)
        && hasRequiredProperties(data, keys, dataPath);
    }
    // min/max/required are three independent assertions about the same
    // object; each is the only thing that can report its own fault.
    let valid = isMinProperties(len, dataPath);
    valid = isMaxProperties(len, dataPath) && valid;
    return hasRequiredProperties(data, keys, dataPath) && valid;
  };
}

/**
 * The collecting walk's parts: the validator of one listed member
 * (`validateMember`), the names that trigger a dependency keyword
 * (`triggers`) and the validator (`validateTrigger`) of one that is an own
 * member Object.keys does not list, which only those keywords read.
 * @param {import('./index.js').ValidationObject} schemaObj
 * @param {object} jsonSchema
 * @returns {{ validateMember: Function, triggers: string[], validateTrigger: Function } | undefined}
 */
function compileObjectProperty(schemaObj, jsonSchema) {
  const namesValidator = compilePropertyNames(schemaObj, jsonSchema);
  const propertyValidator = compileProperties(schemaObj, jsonSchema);
  const patternValidator = compilePatternProperties(schemaObj, jsonSchema);
  const additionalValidator = compileAdditionalProperties(schemaObj, jsonSchema);
  const depSchemasValidator = compileDependentSchemas(schemaObj, jsonSchema);
  const dependencyValidator = compileDependencies(schemaObj, jsonSchema);
  const depRequiredValidator = compileDependentRequired(schemaObj, jsonSchema);

  if ((patternValidator
    || namesValidator
    || propertyValidator
    || depRequiredValidator
    || depSchemasValidator
    || dependencyValidator
    || additionalValidator) == null)
    return undefined;

  const validateName = namesValidator || trueThat;
  const validateProperty = propertyValidator || ValidationResult.undefThat;
  const validatePattern = patternValidator || ValidationResult.undefThat;

  const validateDepRequired = depRequiredValidator || trueThat;
  const validateDepSchemas = depSchemasValidator || trueThat;
  const validateDependency = dependencyValidator || trueThat;

  const validateMember = function validateObjectProperty(data, dataPath, dataRoot, dataKey) {
    const result = new ValidationResult();
    // Build the child dataPath by appending the property key
    const newPath = memberPath(dataPath ?? '', dataKey);

    result.addValid(validateName(dataKey, dataPath))
      .addResult(validateProperty(data, newPath, dataRoot, dataKey))
      .addResult(validatePattern(data, newPath, dataRoot, dataKey))
      .addValid(validateDepRequired(data, newPath, dataRoot, dataKey, dataPath))
      .addValid(validateDepSchemas(data, newPath, dataRoot, dataKey, dataPath))
      .addValid(validateDependency(data, newPath, dataRoot, dataKey, dataPath));

    if (additionalValidator)
      return !result.match
        ? result.addMatch(additionalValidator(data, newPath, dataRoot, dataKey))
        : result;

    return result;
  };

  return {
    validateMember,
    triggers: dependencyTriggers(jsonSchema, depRequiredValidator, depSchemasValidator, dependencyValidator),
    validateTrigger: function validateDependencyTrigger(data, dataPath, dataRoot, dataKey) {
      const newPath = memberPath(dataPath ?? '', dataKey);
      return new ValidationResult()
        .addValid(validateDepRequired(data, newPath, dataRoot, dataKey, dataPath))
        .addValid(validateDepSchemas(data, newPath, dataRoot, dataKey, dataPath))
        .addValid(validateDependency(data, newPath, dataRoot, dataKey, dataPath));
    },
  };
}

/**
 * Fused per-key validation loop for the default skipErrors mode.
 * Avoids the per-key ValidationResult allocations and eagerly built child
 * paths of the generic path; returns on the first failing property.
 * Child paths are still built (lazily) where a location reader below needs
 * them: $data validators resolve relative JSON pointers against them at
 * validation time.
 */
function compileObjectChildrenFast(schemaObj, jsonSchema) {
  const namesValidator = compilePropertyNames(schemaObj, jsonSchema);
  const propsMap = buildPropertyValidators(schemaObj, jsonSchema) || null;
  const patternList = buildPatternValidators(schemaObj, jsonSchema) || null;
  const depSchemasValidator = compileDependentSchemas(schemaObj, jsonSchema) || null;
  const dependencyValidator = compileDependencies(schemaObj, jsonSchema) || null;
  const depRequiredValidator = compileDependentRequired(schemaObj, jsonSchema) || null;

  const root = schemaObj.root;
  const track = root.usesUnevaluated;

  const additional = getBoolOrObjectClass(jsonSchema.additionalProperties);
  const additionalFalse = additional === false;
  const additionalValidator = (additional != null && additional !== false && additional !== true)
    ? schemaObj.createValidator(additional, 'additionalProperties')
    : null;
  // additionalProperties: true evaluates every leftover property, which
  // matters when annotations are tracked for unevaluatedProperties.
  const additionalTrue = additional === true && track;
  const hasAdditional = additionalFalse || additionalTrue || additionalValidator != null;

  if (namesValidator == null
    && propsMap == null
    && patternList == null
    && depSchemasValidator == null
    && dependencyValidator == null
    && depRequiredValidator == null
    && !hasAdditional)
    return undefined;

  const validateName = namesValidator || null;
  // The members that trigger a dependency keyword: a listed member that is
  // one is handed to those keywords, and one that is an own member
  // Object.keys does not list triggers them too, after the listed members.
  // `met` holds a bit for each of the first 31 the listed walk met, which
  // then cost no probe.
  const triggers = dependencyTriggers(jsonSchema, depRequiredValidator, depSchemasValidator, dependencyValidator);
  const triggerCount = triggers.length;
  const triggerAt = triggerCount === 0 ? null : new Map(triggers.map((name, at) => [name, at]));
  /**
   * The dependency keywords an unlisted member triggers, in their order:
   * false at the first that fails (the listed walk calls them itself).
   * @param {object} data
   * @param {string} childPath - The member's location, where one is read
   * @param {unknown} dataRoot
   * @param {string} dataKey
   * @param {string} dataPath - The object's location
   * @returns {boolean}
   */
  const validateTriggered = function validateTriggeredDependencies(data, childPath, dataRoot, dataKey, dataPath) {
    return (depRequiredValidator === null || depRequiredValidator(data, childPath, dataRoot, dataKey, dataPath) !== false)
      && (depSchemasValidator === null || depSchemasValidator(data, childPath, dataRoot, dataKey, dataPath) !== false)
      && (dependencyValidator === null || dependencyValidator(data, childPath, dataRoot, dataKey, dataPath) !== false);
  };

  // In skipErrors mode a member's location is read only by a location reader
  // (`$data`, `data`, `$query`) at or below the member's schema; skip the
  // per-member string concat otherwise.
  const extendPaths = extendsChildLocations(schemaObj, jsonSchema, OBJECT_CHILD_KEYWORDS);

  return function validateObjectChildrenFast(data, dataPath, dataRoot, dataKeys) {
    const len = dataKeys.length;
    let met = 0;
    for (let i = 0; i < len; ++i) {
      const dataKey = dataKeys[i];
      if (validateName != null && validateName(dataKey, dataPath) === false)
        return false;

      let matched = false;
      let childPath = null;

      if (propsMap != null) {
        const propValidator = propsMap.get(dataKey);
        if (propValidator != null) {
          matched = true;
          childPath = extendPaths ? memberPath(dataPath, dataKey) : dataPath;
          if (propValidator(data[dataKey], childPath, dataRoot, dataKey) === false)
            return false;
          if (track) root.evalLog.add(data, dataKey);
        }
      }

      if (patternList != null) {
        for (let j = 0; j < patternList.length; ++j) {
          const entry = patternList[j];
          if (entry.matches(dataKey)) {
            matched = true;
            if (childPath === null) childPath = extendPaths ? memberPath(dataPath, dataKey) : dataPath;
            if (entry.validator(data[dataKey], childPath, dataRoot, dataKey) === false)
              return false;
            if (track) root.evalLog.add(data, dataKey);
          }
        }
      }

      if (matched === false && hasAdditional) {
        if (additionalFalse)
          return false;
        if (additionalValidator != null) {
          if (childPath === null) childPath = extendPaths ? memberPath(dataPath, dataKey) : dataPath;
          if (additionalValidator(data[dataKey], childPath, dataRoot, dataKey) === false)
            return false;
        }
        if (track) root.evalLog.add(data, dataKey);
      }

      if (triggerAt !== null) {
        const at = triggerAt.get(dataKey);
        if (at !== undefined) {
          if (at < 31) met |= 1 << at;
          if (childPath === null) childPath = extendPaths ? memberPath(dataPath, dataKey) : dataPath;
          if (depRequiredValidator !== null && depRequiredValidator(data, childPath, dataRoot, dataKey, dataPath) === false)
            return false;
          if (depSchemasValidator !== null && depSchemasValidator(data, childPath, dataRoot, dataKey, dataPath) === false)
            return false;
          if (dependencyValidator !== null && dependencyValidator(data, childPath, dataRoot, dataKey, dataPath) === false)
            return false;
        }
      }
    }
    for (let at = 0; at < triggerCount; ++at) {
      const dataKey = triggers[at];
      if ((at < 31 ? (met & (1 << at)) === 0 && Object.hasOwn(data, dataKey) : isUnlistedMember(data, dataKeys, dataKey))
        && !validateTriggered(data, extendPaths ? memberPath(dataPath, dataKey) : dataPath, dataRoot, dataKey, dataPath))
        return false;
    }
    return true;
  };
}

export function compileObjectChildren(schemaObj, jsonSchema) {
  // Fast path: when errors are skipped (default) we can bail on the first
  // failure and avoid per-key result bookkeeping entirely.
  // (unevaluatedProperties runs separately as a final-stage validator,
  // see unevaluated.js)
  if (schemaObj.options.skipErrors)
    return compileObjectChildrenFast(schemaObj, jsonSchema);

  // `properties` where it reads each member it names by a probe.
  if (readsNamedMembers(jsonSchema))
    return compileNamedMembers(schemaObj, buildPropertyValidators(schemaObj, jsonSchema));

  const compiled = compileObjectProperty(schemaObj, jsonSchema);
  if (compiled == null)
    return undefined;
  const { validateMember: propertyValidator, triggers, validateTrigger } = compiled;
  const triggerCount = triggers.length;

  // Inline ValidationResult operations to reduce object allocations
  return function validateObjectChildren(data, dataPath, dataRoot, dataKeys) {
    let totalErrors = 0;
    const len = dataKeys.length;
    for (let i = 0; i < len; ++i) {
      const result = propertyValidator(data, dataPath, dataRoot, dataKeys[i]);
      if (result !== true) {
        // result can be false or a ValidationResult-like object
        if (result === false) {
          totalErrors++;
        } else {
          totalErrors += result.errors || 0;
        }
      }
    }
    // A member that triggers a dependency keyword and is an own member
    // Object.keys does not list triggers it too, after the listed members.
    for (let i = 0; i < triggerCount; ++i) {
      if (isUnlistedMember(data, dataKeys, triggers[i]))
        totalErrors += validateTrigger(data, dataPath, dataRoot, triggers[i]).errors;
    }
    return totalErrors === 0;
  };
}

/**
 * The collecting walk of a schema whose `properties` reads each member it
 * names by a probe (readsNamedMembers), the keyword being the only one of
 * its object group that reads a member: the listed members in their order,
 * each named one read by its schema as the general walk reads it, then each
 * named member the list does not hold, when it is an own member (the
 * first-failure walk of the shape, compilePropertiesWalk, probes every name
 * it declares). A name the listed walk met costs no probe.
 * @param {import('./index.js').ValidationObject} schemaObj
 * @param {Map<string, Function> | undefined} validators - The validators of the named members
 * @returns {Function | undefined}
 */
function compileNamedMembers(schemaObj, validators) {
  if (validators == null) return undefined;

  const root = schemaObj.root;
  const track = root.usesUnevaluated;
  const logFailed = annotatesFailedMembers(schemaObj);
  const names = Array.from(validators.keys());
  const memberValidators = Array.from(validators.values());
  const count = names.length;
  const positions = new Map(names.map((name, at) => [name, at]));
  /**
   * Whether the member named at position `at` fails its schema; what it
   * evaluates is logged as the general walk logs it.
   * @param {object} data
   * @param {string} dataPath - The object's location
   * @param {unknown} dataRoot
   * @param {string} dataKey
   * @param {number} at
   * @returns {boolean}
   */
  const failsAt = function failsNamedMember(data, dataPath, dataRoot, dataKey, at) {
    const valid = memberValidators[at](data[dataKey], memberPath(dataPath ?? '', dataKey), dataRoot, dataKey);
    if (track && (valid === true || logFailed)) root.evalLog.add(data, dataKey);
    return valid === false;
  };

  return function validateObjectNamedMembers(data, dataPath, dataRoot, dataKeys) {
    let errors = 0;
    // the names met among the listed members: a bit each, or a byte each
    // where a schema names more than 31
    let met = 0;
    const wide = count > 31 ? new Uint8Array(count) : null;
    const len = dataKeys.length;
    for (let i = 0; i < len; ++i) {
      const dataKey = dataKeys[i];
      const at = positions.get(dataKey);
      if (at === undefined) continue;
      if (wide === null) met |= 1 << at;
      else wide[at] = 1;
      if (failsAt(data, dataPath, dataRoot, dataKey, at)) errors++;
    }
    for (let at = 0; at < count; ++at) {
      if (wide === null ? (met & (1 << at)) !== 0 : wide[at] === 1) continue;
      if (Object.hasOwn(data, names[at]) && failsAt(data, dataPath, dataRoot, names[at], at)) errors++;
    }
    return errors === 0;
  };
}


/**
 * The validator of a schema's object keywords, or undefined when it holds
 * none that asserts anything.
 * @param {import('./index.js').ValidationObject} schemaObj
 * @param {object} jsonSchema
 * @param {{ error: (data: unknown, dataPath: string) => boolean, taken: boolean } | null} [typed] -
 *   A leading `type: 'object'` no other keyword group precedes, in the
 *   first-failure mode: the validator then tests it too, failing through
 *   `typed.error`, and sets `typed.taken`
 * @returns {Function | undefined}
 */
export function compileObjectSchema(schemaObj, jsonSchema, typed = null) {
  const validate = compileObjectGroup(schemaObj, jsonSchema, typed === null ? null : typed.error);
  if (typed !== null && validate !== undefined)
    typed.taken = true;
  // A Map that a `map` type takes is that type's to read, not the object
  // keywords'; they apply to every other object whatever else the type names.
  if (validate !== undefined && isOfSchemaType(jsonSchema, 'map')) {
    return function validateObjectBesideMap(data, dataPath, dataRoot, dataKey) {
      return isMapClass(data) || validate(data, dataPath, dataRoot, dataKey);
    };
  }
  return validate;
}

// The member tests a member walk calls no closure for, in the order
// isPureMember switches on them: a schema asserting nothing, then the
// shared type-only tests (typeOnlyTest in tools.js).
const PURE_MEMBERS = [trueThat, isTypeOnlyString, isTypeOnlyNumber, isTypeOnlyInteger,
  isTypeOnlyBoolean, isTypeOnlyArray, isTypeOnlyObject, isTypeOnlyNull];

/**
 * The answer of the member test at `code` (a PURE_MEMBERS index), called by
 * name: a walk testing a member through it calls no closure.
 * @param {number} code
 * @param {unknown} data
 * @returns {boolean}
 */
function isPureMember(code, data) {
  switch (code) {
    case 0: return trueThat(data);
    case 1: return isTypeOnlyString(data);
    case 2: return isTypeOnlyNumber(data);
    case 3: return isTypeOnlyInteger(data);
    case 4: return isTypeOnlyBoolean(data);
    case 5: return isTypeOnlyArray(data);
    case 6: return isTypeOnlyObject(data);
    default: return isTypeOnlyNull(data);
  }
}

/**
 * The fast path's member walks, in skipErrors mode: `properties` (whose
 * validators `propsMap` holds) with `required`, alone or with
 * `additionalProperties` (`closed`). A member whose schema is type-only or
 * asserts nothing is tested by code (isPureMember), any other by its
 * validator. A `required` name `properties` declares is tested where its
 * member is read, once; the other `required` names before any member is.
 * @param {import('./index.js').ValidationObject} schemaObj
 * @param {object} jsonSchema
 * @param {Map<string, Function>} propsMap
 * @param {boolean} closed
 * @param {((data: unknown, dataPath: string) => boolean) | null} typeError - A leading type's fault (compileObjectSchema)
 * @returns {Function}
 */
function compilePropertiesWalk(schemaObj, jsonSchema, propsMap, closed, typeError) {
  // required belongs to the validation vocabulary; assert nothing when
  // the metaschema disables it.
  const requiredNames = new Set(schemaObj.options.vocabValidation !== false
    ? getArrayClassMinItems(jsonSchema.required, 1)
    : undefined);

  const propKeys = Array.from(propsMap.keys());
  const propValidators = Array.from(propsMap.values());
  const propCount = propKeys.length;
  const codes = propValidators.map((validator) => PURE_MEMBERS.indexOf(validator));
  const requiredAt = propKeys.map((key) => requiredNames.has(key));
  const requiredDeclared = propKeys.filter((key) => requiredNames.has(key));
  const requiredRest = Array.from(requiredNames).filter((key) => !propsMap.has(key));
  const restCount = requiredRest.length;

  if (closed) {
    const additional = getBoolOrObjectClass(jsonSchema.additionalProperties);
    const additionalFalse = additional === false;
    const additionalValidator = (additional != null && additional !== false && additional !== true)
      ? schemaObj.createValidator(additional, 'additionalProperties')
      : null;
    const additionalCode = additionalValidator === null ? -1 : PURE_MEMBERS.indexOf(additionalValidator);
    const propIndex = new Map(propKeys.map((key, i) => [key, i]));
    const declaredCount = requiredDeclared.length;

    // The general path's walk: the instance's own enumerable keys in their
    // order (those Object.keys lists, which `for…in` visits first and
    // V8 tests for ownness from its enumeration cache), so a member
    // additionalProperties refuses answers before any member after it is
    // read. A key at the schema's next position is matched without the map.
    // A declared `required` name the walk does not meet may still be an own
    // non-enumerable member: those are probed after it.
    return function validateObjectClosedProperties(data, dataPath, dataRoot) {
      if (!isObjectInstance(data)) return otherKind(typeError, data, dataPath);
      for (let i = 0; i < restCount; ++i) {
        if (!Object.hasOwn(data, requiredRest[i]))
          return false;
      }
      let next = 0;
      let met = 0;
      for (const key in data) {
        if (!hasOwnProperty.call(data, key)) continue;
        const at = key === propKeys[next] ? next : propIndex.get(key);
        if (at !== undefined) {
          next = at + 1;
          if (requiredAt[at]) ++met;
          const code = codes[at];
          if (code >= 0 ? !isPureMember(code, data[key]) : propValidators[at](data[key], dataPath, dataRoot, key) === false)
            return false;
        }
        else if (additionalFalse)
          return false;
        else if (additionalValidator !== null && (additionalCode >= 0
          ? !isPureMember(additionalCode, data[key])
          : additionalValidator(data[key], dataPath, dataRoot, key) === false))
          return false;
      }
      return met === declaredCount || hasOwnAll(data, requiredDeclared);
    };
  }

  const root = schemaObj.root;
  const track = root.usesUnevaluated;

  // In skipErrors mode a member's location is read only by a location reader
  // at or below the member's schema; skip the per-property string concat
  // otherwise.
  const extendPaths = extendsChildLocations(schemaObj, jsonSchema, OBJECT_CHILD_KEYWORDS);
  if (extendPaths || track) {
    return function validateObjectPropertiesOnlyTracked(data, dataPath, dataRoot) {
      if (!isObjectInstance(data)) return otherKind(typeError, data, dataPath);
      for (let i = 0; i < restCount; ++i) {
        if (!Object.hasOwn(data, requiredRest[i]))
          return false;
      }
      for (let i = 0; i < propCount; ++i) {
        const key = propKeys[i];
        // Object.hasOwn: avoid picking up inherited members like toString
        if (Object.hasOwn(data, key)) {
          const childPath = extendPaths ? memberPath(dataPath, key) : dataPath;
          if (propValidators[i](data[key], childPath, dataRoot, key) === false)
            return false;
          if (track) root.evalLog.add(data, key);
        }
        else if (requiredAt[i])
          return false;
      }
      return true;
    };
  }

  return function validateObjectPropertiesOnly(data, dataPath, dataRoot) {
    if (!isObjectInstance(data)) return otherKind(typeError, data, dataPath);
    for (let i = 0; i < restCount; ++i) {
      if (!Object.hasOwn(data, requiredRest[i]))
        return false;
    }
    for (let i = 0; i < propCount; ++i) {
      const key = propKeys[i];
      // Object.hasOwn: avoid picking up inherited members like toString
      if (Object.hasOwn(data, key)) {
        const code = codes[i];
        if (code >= 0 ? !isPureMember(code, data[key]) : propValidators[i](data[key], dataPath, dataRoot, key) === false)
          return false;
      }
      else if (requiredAt[i])
        return false;
    }
    return true;
  };
}

function compileObjectGroup(schemaObj, jsonSchema, typeError) {
  // Fast path: properties(+required) in skipErrors mode, alone or with
  // additionalProperties. Alone, the walk iterates the (fixed) schema keys
  // with direct property access instead of allocating Object.keys(data) and
  // doing a map lookup per data key; required membership is a per-key
  // Object.hasOwn probe, made once for a name properties also declares.
  // With additionalProperties, where no annotation is kept and no member
  // location is read, it walks the instance's own enumerable keys as the
  // general path does, with fewer calls and no key list.
  const closed = jsonSchema.additionalProperties != null;
  if (schemaObj.options.skipErrors
    && holdsPropertiesOnly(jsonSchema)
    && (!closed || (!schemaObj.root.usesUnevaluated
      && !extendsChildLocations(schemaObj, jsonSchema, OBJECT_CHILD_KEYWORDS)))) {
    const propsMap = buildPropertyValidators(schemaObj, jsonSchema);
    // A `properties` naming no member leaves `required` to the general path.
    if (propsMap != null)
      return compilePropertiesWalk(schemaObj, jsonSchema, propsMap, closed, typeError);
  }

  const objectPrimitives = compileObjectPrimitives(schemaObj, jsonSchema);
  const objectChildren = compileObjectChildren(schemaObj, jsonSchema);

  if ((objectPrimitives
    || objectChildren) == null)
    return undefined;

  const validatePrimitives = objectPrimitives || trueThat;
  const validateChildren = objectChildren || trueThat;

  // Without child validators the data keys are only consumed by the
  // min/max length checks, which compute them on demand; skip the
  // per-validation Object.keys allocation.
  if (objectChildren == null) {
    return function validateObjectPrimitivesSchema(data, dataPath, dataRoot) {
      if (isObjectInstance(data)) {
        return validatePrimitives(data, dataPath, dataRoot, undefined);
      }
      return otherKind(typeError, data, dataPath);
    };
  }

  if (schemaObj.options.skipErrors) {
    return function validateObjectSchema(data, dataPath, dataRoot) {
      if (isObjectInstance(data)) {
        const dataKeys = Object.keys(data);
        return validatePrimitives(data, dataPath, dataRoot, dataKeys)
          && validateChildren(data, dataPath, dataRoot, dataKeys);
      }
      return otherKind(typeError, data, dataPath);
    };
  }

  // `required`/`minProperties` and the per-property schemas are independent:
  // the child walk re-derives everything it needs from the data and cannot
  // fault on a missing key. Stopping after a missing `required` would report
  // the absent property and hide every fault in the properties that ARE
  // present, which is the difference between one issue and a usable list.
  return function validateObjectSchemaAll(data, dataPath, dataRoot) {
    if (isObjectInstance(data)) {
      const dataKeys = Object.keys(data);
      const primitives = validatePrimitives(data, dataPath, dataRoot, dataKeys);
      return validateChildren(data, dataPath, dataRoot, dataKeys) && primitives;
    }
    return otherKind(typeError, data, dataPath);
  };
}
